export const quotes1000: Quote[] = [
  // ========== 해외 영화·드라마 명대사 (300개) ==========
  
  // 공부와 노력
  { text: "우리는 모두 바쁜 삶 속에서 시간을 보내죠.\n하지만 결국 그 바쁨이 우리를 어디로 데려갈지 모르는 법이에요.\n바쁘게 살아가는 것과 바쁘게 떠나는 것 사이에서,\n무엇을 위해 달려가고 있는지 마음 깊이 돌아보는 시간이 필요해요.", source: "영화 쇼생크 탈출 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "희망은 때로 우리에게 위험처럼 느껴질 수 있어요.\n하지만 그 희망이 바로 우리를 자유롭게 만들고,\n새로운 길을 향해 나아가게 하는 힘이 되어준답니다.", source: "영화 쇼생크 탈출 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "어떤 새들은 자유로운 영혼을 가졌기에\n어떤 울타리도 그들을 가두지 못해요.\n그들은 하늘 높이 날아올라 자신의 길을 찾아가죠.", source: "영화 쇼생크 탈출 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "당신이 할 수 있다고 믿는 순간, 이미 그 길의 절반은 걸어간 셈이에요.\n반대로 할 수 없다고 생각할 때에는, 그 마음이 당신의 발걸음을 멈추게 하죠.\n결국 중요한 것은 당신의 생각이며, 그 믿음이 현실을 만들어 갑니다.", source: "영화 포레스트 검프 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "인생은 마치 초콜릿 상자와 같아요.  \n안에 무엇이 들어 있을지 미리 알 수 없기에,  \n그 기다림과 설렘 속에서 매일이 특별해지는 거랍니다.", source: "영화 포레스트 검프 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "오늘이라는 이 순간이  \n너의 인생에서 가장 소중하고 중요한 날이란 걸 기억해 줘.  \n지금 여기에서 시작하는 모든 것이 너의 미래를 만들어 가니까,  \n오늘을 소중히 살아가길 바란다.", source: "영화 포레스트 검프 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "계속해서 한 걸음씩 나아가야 해요.\n비록 힘들고 지칠 때도 있겠지만,\n포기하지 않고 앞으로 나아가는 그 마음이 우리를 성장하게 해줄 거예요.", source: "영화 포레스트 검프 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "우리는 매일 반복하는 작은 행동들의 모임이에요.\n그래서 진정한 탁월함은 순간의 선택이 아니라,\n꾸준히 쌓아가는 습관 속에서 피어나는 법이랍니다.", source: "영화 인터스텔라 (2014)", category: "공부와 노력", type: "foreign-movie" },
  { text: "우리는 때로 어둠 속에 홀로 남겨진 것처럼 느낄 때가 있어요.\n그럴 때일수록 더욱 마음을 다해 작은 빛을 찾아야만 해요.\n그 빛이 우리를 앞으로 나아가게 하는 힘이 되어 줄 테니까요.", source: "영화 인터스텔라 (2014)", category: "공부와 노력", type: "foreign-movie" },
  { text: "절대 포기하지 마세요.\n눈앞에 불가능해 보이는 일들도\n조금씩 다가가다 보면 언젠가는 가능해질 거예요.", source: "영화 인터스텔라 (2014)", category: "공부와 노력", type: "foreign-movie" },
  { text: "시간은 누구에게나 똑같이 흐르지만, 그 속도와 무게는 각자 다르게 느껴집니다.  \n중요한 것은 그 흘러가는 시간을 어떻게 채우고, 어떤 의미로 만드는가에 달려 있어요.  \n그래서 우리는 매 순간을 소중히 여기며 마음을 담아 살아가야 합니다.", source: "영화 인터스텔라 (2014)", category: "공부와 노력", type: "foreign-movie" },
  { text: "우리는 우리 안에 숨겨진 한계를 쉽게 알지 못해요.\n하지만 용기 내어 한 걸음 내딛고 시도할 때,\n비로소 그 한계가 어디인지 조금씩 알게 된답니다.", source: "영화 인터스텔라 (2014)", category: "공부와 노력", type: "foreign-movie" },
  { text: "가장 큰 성취는 언제나 가장 큰 위험을 감수할 때 찾아옵니다.  \n두려움 앞에서도 한 걸음 내딛는 용기야말로  \n우리 삶을 빛나게 만드는 소중한 열쇠가 되어줍니다.", source: "영화 인터스텔라 (2014)", category: "공부와 노력", type: "foreign-movie" },
  { text: "우리는 매일매일 수많은 선택을 하며 살아가요.\n그 작은 선택들이 모여 결국 우리 자신을 만들어 가는 거예요.\n그래서 우리의 삶은 바로 우리가 내린 결정들의 소중한 반영이랍니다.", source: "영화 배트맨 비긴즈 (2005)", category: "공부와 노력", type: "foreign-movie" },
  { text: "공포는 우리에게 힘을 주는 도구와 같아요.\n그 두려움을 마주하고 활용할 때, 불가능해 보였던 일들도\n조금씩 가능의 영역으로 다가올 수 있답니다.", source: "영화 배트맨 비긴즈 (2005)", category: "공부와 노력", type: "foreign-movie" },
  { text: "진정한 힘이란 외부에서 오는 것이 아니라,\n우리 안에 숨겨진 두려움을 마주하고 이겨낼 때 비로소 피어나는 것입니다.\n두려움을 넘어설 때, 우리는 한층 더 강해지고 성장할 수 있어요.", source: "영화 배트맨 비긴즈 (2005)", category: "공부와 노력", type: "foreign-movie" },
  { text: "우리가 마음 깊이 믿는 것들은\n언젠가 우리 삶의 진짜 모습이 되어 나타나요.\n그 믿음이 바로 우리의 현실을 만들어 가는 힘이니까요.", source: "영화 배트맨 비긴즈 (2005)", category: "공부와 노력", type: "foreign-movie" },
  { text: "실패는 결코 끝이 아니에요.\n오히려 성공이라는 아름다운 열매를 맺게 하는 소중한 어머니와 같답니다.\n그 품에서 우리는 다시 일어나 더 단단해질 수 있지요.", source: "영화 라이온 킹 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "과거는 이미 지나간 시간일 뿐이에요.\n그 속에 머무르기보다는,\n지금 이 순간에 집중하는 것이 진정 중요한 일이랍니다.", source: "영화 라이온 킹 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "너는 과연 누구인지 깊이 생각해 보았나요?\n자신만의 진짜 모습을 찾아가는 여정은 쉽지 않지만,\n그 길 위에서 비로소 진정한 나를 만날 수 있을 거예요.", source: "영화 라이온 킹 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "두려움이 마음을 무겁게 할 때에도 멈추지 말고 한 걸음씩 내딛으세요.\n그 길 끝에는 분명히 당신을 기다리는 새로운 기회와 성장의 씨앗이 있습니다.  \n용기 내어 앞으로 나아가는 그 자체가 이미 당신의 가장 큰 승리입니다.", source: "영화 라이온 킹 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "너의 운명은 멀리 있는 누군가에게 맡겨진 것이 아니에요.\n바로 너 자신이 만들어 가는 것이기에,\n그 손길 하나하나가 소중하고 값지답니다.", source: "영화 라이온 킹 (1994)", category: "공부와 노력", type: "foreign-movie" },
  { text: "계획을 세우고 차근차근 실행해 나가면\n그 길 끝에는 분명히 성공이 기다리고 있어요.\n포기하지 않고 꾸준히 나아가는 힘을 믿으세요.", source: "영화 다크 나이트 (2008)", category: "공부와 노력", type: "foreign-movie" },
  { text: "진정한 영웅은 언제나 자신을 먼저 내어줍니다.\n그들의 희생은 말없이 세상을 조금 더 따뜻하게 만들죠.\n우리는 그런 마음에서 진정한 용기를 배울 수 있습니다.", source: "영화 다크 나이트 (2008)", category: "공부와 노력", type: "foreign-movie" },
  { text: "우리가 두려워하는 그 순간들이 사실은 우리를 한층 더 단단하게 만들어 줍니다.\n두려움 속에서 마주한 자신을 믿고 나아갈 때,\n비로소 내면의 힘이 자라나는 것을 느낄 수 있을 거예요.", source: "영화 다크 나이트 (2008)", category: "공부와 노력", type: "foreign-movie" },
  { text: "혼자가 아니라는 것을 잊지 마세요.\n세상 어딘가에서는 항상 누군가가 당신을 바라보며\n조용히 응원의 마음을 보내고 있을 거예요.", source: "영화 다크 나이트 (2008)", category: "공부와 노력", type: "foreign-movie" },
  { text: "작은 시작이 때로는 세상을 바꾸는 첫걸음이 됩니다.\n비록 미미해 보여도 그 한 걸음이 모여 큰 변화를 이루는 법이니까요.  \n조금씩 꾸준히 나아가는 마음을 잃지 않는다면,\n언젠가 그 노력들이 빛나는 결실로 돌아올 거예요.", source: "영화 다크 나이트 (2008)", category: "공부와 노력", type: "foreign-movie" },
  { text: "너는 지금 이 순간에도 충분히 잘하고 있어요.\n어려운 길 위에서 흔들릴 때마다,\n조금씩 앞으로 나아가고 있다는 사실을 잊지 마세요. 계속해서 나아가면 분명 빛나는 내일이 기다리고 있을 거예요.", source: "드라마 브레이킹 배드 (2008)", category: "공부와 노력", type: "foreign-movie" },
  { text: "결과가 전부라고 하지만,\n과정 또한 우리를 성장하게 하는 소중한 시간이란 걸 잊지 말아요.\n비록 눈에 보이는 성과에 마음이 집중되지만,\n그 과정 속에서 배우고 느끼는 것들이 결국 우리를 더 단단하게 만들죠.", source: "드라마 브레이킹 배드 (2008)", category: "공부와 노력", type: "foreign-movie" },
  { text: "인생에서 가장 중요한 순간들은 늘 선택의 기로에 서 있을 때 찾아와요.\n그 작은 결정들이 모여 우리의 길을 만들어 가기에,\n한 걸음 한 걸음 신중하고 따뜻한 마음으로 걸어가야 해요.", source: "드라마 브레이킹 배드 (2008)", category: "공부와 노력", type: "foreign-movie" },
  { text: "후회는 우리의 마음을 무겁게 만들 뿐이에요.\n그러니 지나간 일에 얽매이지 말고,\n지금 이 순간에 최선을 다하며 살아가세요.", source: "드라마 브레이킹 배드 (2008)", category: "공부와 노력", type: "foreign-movie" },
  
  // 극복과 도전
  { text: "불가능이라는 것은 사실 존재하지 않아요.\n아직 우리가 그 길을 걸어보지 않았을 뿐이니까요.\n조금만 더 용기를 내어 시도해 보면,\n언젠가는 반드시 새로운 가능성을 발견할 거예요.", source: "영화 아바타 (2009)", category: "극복과 도전", type: "foreign-movie" },
  { text: "우리는 때로 약점이라 생각하는 부분에서 진정한 힘을 발견할 수 있어요.  \n그 약점을 조금씩 다듬고 받아들이며,\n스스로의 강점으로 만들어 나가는 과정이야말로 성장의 시작이랍니다.", source: "영화 아바타 (2009)", category: "극복과 도전", type: "foreign-movie" },
  { text: "진정한 전사는 외부의 적보다도\n자신 안에 숨겨진 두려움과 맞서 싸웁니다.\n그 용기야말로 진정한 강함의 시작이지요.", source: "영화 아바타 (2009)", category: "극복과 도전", type: "foreign-movie" },
  { text: "모두가 너를 믿지 않는다고 해도 괜찮아.\n중요한 건 바로 너 자신을 믿는 마음이니까.\n그 믿음이 너를 앞으로 나아가게 하는 가장 큰 힘이 될 거야.", source: "영화 아바타 (2009)", category: "극복과 도전", type: "foreign-movie" },
  { text: "위기는 우리에게 닥친 어려움이지만,\n그 속에는 반드시 새로운 기회가 숨어 있어요.\n힘들 때일수록 마음을 다잡고 한 걸음 더 나아가면,\n빛나는 가능성을 발견할 수 있답니다.", source: "영화 아바타 (2009)", category: "극복과 도전", type: "foreign-movie" },
  { text: "나는 할 수 있다는 믿음을 가슴에 품고 있어요.\n어떤 어려움이 와도 포기하지 않고,\n반드시 해내겠다는 결심으로 나아갈 거예요.", source: "영화 록키 (1976)", category: "극복과 도전", type: "foreign-movie" },
  { text: "진정한 챔피언이 되는 것만이 중요한 게 아니에요.\n무엇보다 중요한 것은 매 순간 자신을 믿고,\n챔피언처럼 용기 있고 당당하게 행동하는 것입니다.", source: "영화 록키 (1976)", category: "극복과 도전", type: "foreign-movie" },
  { text: "고통은 결코 약함을 의미하는 것이 아니에요.\n오히려 그 고통 속에서 우리는 스스로의 강함을 발견하게 됩니다.\n힘들고 아플 때마다, 당신은 더 단단해지고 있다는 증거인 셈이니까요.", source: "영화 록키 (1976)", category: "극복과 도전", type: "foreign-movie" },
  { text: "계속해서 한 걸음씩 나아가는 것만이 진정한 승리입니다.\n비록 길이 멀고 힘들지라도 멈추지 않고 앞으로 나아갈 때,\n마침내 그 모든 노력들이 빛을 발하게 될 거예요.", source: "영화 록키 (1976)", category: "극복과 도전", type: "foreign-movie" },
  { text: "너는 스스로 생각하는 것보다 훨씬 더 강한 사람이에요.\n때로는 힘들고 지칠 때도 있겠지만,\n그 모든 순간을 견뎌내는 너의 내면은 정말 단단하답니다.", source: "영화 록키 (1976)", category: "극복과 도전", type: "foreign-movie" },
  { text: "절대 포기하지 말아요.\n어떤 어려움이 찾아와도,\n그 끝에는 반드시 새로운 희망이 기다리고 있으니까요.", source: "영화 인셉션 (2010)", category: "극복과 도전", type: "foreign-movie" },
  { text: "꿈은 우리 마음속 깊이 숨겨진 소중한 씨앗과 같아요.\n진심을 다해 노력할 때마다 그 씨앗은 자라나,\n언젠가는 반드시 현실이라는 아름다운 꽃을 피울 거예요.", source: "영화 인셉션 (2010)", category: "극복과 도전", type: "foreign-movie" },
  { text: "우리는 우리의 마음속 깊은 곳에서부터 시작하여\n무엇이든 이루어낼 수 있는 힘을 가지고 있어요.\n그 믿음이야말로 세상을 바꾸는 가장 큰 원동력이랍니다.", source: "영화 인셉션 (2010)", category: "극복과 도전", type: "foreign-movie" },
  { text: "현실과 꿈 사이의 경계는 아주 얇아서\n때로는 그 차이를 느끼기 어려울 때가 있어요.\n어떤 마음가짐으로 바라보느냐에 따라\n그 경계가 분명해지기도, 흐려지기도 한답니다.", source: "영화 인셉션 (2010)", category: "극복과 도전", type: "foreign-movie" },
  { text: "한 걸음씩 천천히 앞으로 나아가다 보면\n어느새 멀게만 느껴졌던 목표에 다다르게 돼요.\n조금씩 쌓아가는 노력들이 결국 큰 결실을 맺는답니다.", source: "영화 인셉션 (2010)", category: "극복과 도전", type: "foreign-movie" },
  { text: "고통이 없이는 진정한 성장은 이루어지지 않아요.\n아픔과 어려움을 겪을 때마다 우리 안에 숨어 있던 힘과 지혜가 조금씩 자라나니까요.\n그 과정을 지나야만 더 깊고 단단한 나로 거듭날 수 있답니다.", source: "영화 매트릭스 (1999)", category: "극복과 도전", type: "foreign-movie" },
  { text: "너는 이미 그 답을 마음속 깊이 알고 있어요.\n그저 아직 그 진실을 완전히 깨닫지 못했을 뿐이랍니다.\n조금만 더 마음을 열고 자신을 믿어 보세요.", source: "영화 매트릭스 (1999)", category: "극복과 도전", type: "foreign-movie" },
  { text: "무엇이든 스스로 선택하는 용기를 가지세요.\n그리고 그 선택에 대한 책임도 따뜻한 마음으로 받아들이는 것이 진정한 성장입니다.  \n자신의 길을 믿고 걸어가는 당신을 응원합니다.", source: "영화 매트릭스 (1999)", category: "극복과 도전", type: "foreign-movie" },
  { text: "우리는 매일 크고 작은 선택을 하며 살아가요.\n그 선택들이 모여서 결국 우리 자신을 만들어가고,\n그래서 우리는 우리의 선택으로 정의된답니다.", source: "영화 매트릭스 (1999)", category: "극복과 도전", type: "foreign-movie" },
  { text: "진실은 언제나 그 자리에 변함없이 존재해요.\n비록 힘들고 어려운 순간이 있더라도,\n결국에는 진실이 우리를 이끌고 승리하게 해준답니다.", source: "영화 매트릭스 (1999)", category: "극복과 도전", type: "foreign-movie" },
  { text: "너는 지금 이대로도 이미 충분히 소중하고 아름다워요.\n물론 앞으로 더 성장하고 변화할 수 있지만,\n그 과정 속에서도 네 가치는 변하지 않는답니다.", source: "영화 글래디에이터 (2000)", category: "극복과 도전", type: "foreign-movie" },
  { text: "명예는 단순한 말이나 약속에서 오는 것이 아니에요.\n진심 어린 행동과 꾸준한 노력으로 차곡차곡 쌓아가는 것이죠.\n그래서 우리의 작은 선택과 행동들이 결국 진정한 명예를 만들어 갑니다.", source: "영화 글래디에이터 (2000)", category: "극복과 도전", type: "foreign-movie" },
  { text: "고통은 때때로 우리를 힘들게 하지만,\n그 안에서 우리는 진정한 강함을 발견하게 됩니다.\n어려움을 견뎌낼 때마다 한층 더 단단해지는 자신을 느껴보세요.", source: "영화 글래디에이터 (2000)", category: "극복과 도전", type: "foreign-movie" },
  { text: "우리는 매일 작은 선택들을 통해\n조금씩 우리의 운명을 빚어 나갑니다.\n그 길이 어떻든, 결국 그 모든 순간이 모여\n우리만의 이야기가 완성되는 거예요.", source: "영화 글래디에이터 (2000)", category: "극복과 도전", type: "foreign-movie" },
  { text: "죽음을 두려워하며 두 발을 멈추지 말아요.\n오히려 매 순간을 소중히 여기며,\n의미 있는 삶을 가꾸어 가는 것이 진정한 용기입니다.", source: "영화 글래디에이터 (2000)", category: "극복과 도전", type: "foreign-movie" },
  { text: "작은 것부터 차근차근 시작해보세요.  \n처음에는 미미해 보여도, 그 한 걸음 한 걸음이 쌓여서  \n결국에는 큰 성과와 기쁨으로 돌아올 거예요.", source: "드라마 게임 오브 스로운즈 (2011)", category: "극복과 도전", type: "foreign-movie" },
  { text: "겨울이 조용히 다가오고 있어요.\n차가운 바람과 함께 찾아올 시간에 맞서,\n마음과 몸을 따뜻하게 준비해야 할 때입니다.", source: "드라마 게임 오브 스로운즈 (2011)", category: "극복과 도전", type: "foreign-movie" },
  { text: "진정한 복수는 상대방을 넘어서는 것이 아니라, 자신의 삶을 꿋꿋이 이어가는 데 있어요.\n어떤 상처와 아픔이 있어도 포기하지 않고 살아가는 것, 그것이야말로 가장 강력한 힘이고 최고의 복수랍니다.", source: "드라마 게임 오브 스로운즈 (2011)", category: "극복과 도전", type: "foreign-movie" },
  { text: "약한 마음도 시간이 지나면 단단해질 수 있어요.\n스스로의 약함을 인정하고 받아들일 때, 그것이 진정한 강함으로 자라납니다.\n그러니 두려워 말고, 자신의 약함을 용기 있게 마주하세요.", source: "드라마 게임 오브 스로운즈 (2011)", category: "극복과 도전", type: "foreign-movie" },
  
  // 꿈과 목표
  { text: "큰 꿈을 품고 나아가세요.  \n그 꿈이 여러분의 마음을 밝히고,  \n결국에는 뜻깊은 성취로 이어질 거예요.", source: "영화 라라랜드 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "너의 꿈은 단순한 바람이 아니에요.\n그것은 바로 너 자신을 이루는 조각이며,\n네가 누구인지 말해주는 가장 깊은 이야기랍니다.", source: "영화 라라랜드 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "꿈을 이루는 일은 결코 쉽지 않아요.\n수많은 어려움과 고비가 찾아오지만,\n그럼에도 불구하고 꿈은 언제나 가능하답니다.", source: "영화 라라랜드 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "목표를 향해 한 걸음씩 꾸준히 나아가세요.\n비록 길이 험하고 멀게 느껴질지라도,\n그 여정 속에서 당신은 점점 더 강해질 거예요.", source: "영화 라라랜드 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "너의 꿈은 너만의 소중한 별과 같아.\n어둠 속에서도 빛을 잃지 않고\n끝까지 그 빛을 따라가야 해.", source: "영화 라라랜드 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "목표는 우리 삶의 나침반과 같아요.\n분명할수록 흔들림 없이 한 걸음씩 나아갈 수 있지요.\n그래서 마음속에 선명하게 그려야 해요, 나만의 길을.", source: "영화 소셜 네트워크 (2010)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "작고 사소한 생각으로는 큰 변화를 이루기 어렵습니다.\n우리가 꿈꾸는 크고 아름다운 세상은,\n더 넓고 깊은 마음에서부터 시작된다는 것을 잊지 마세요.", source: "영화 소셜 네트워크 (2010)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "세상을 바꾸고 싶다면,\n무엇보다 먼저 너 자신부터 깊이 돌아봐야 해요.\n내면이 변할 때 비로소 세상도 조금씩 달라지기 시작하니까요.", source: "영화 소셜 네트워크 (2010)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "성공은 단순한 우연의 산물이 아니에요.\n그것은 끊임없이 노력하며 스스로를 준비한 사람에게만 찾아오는 선물과 같답니다.\n그러니 오늘도 작은 일에 최선을 다하며 스스로를 가꾸어 나가세요.", source: "영화 소셜 네트워크 (2010)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "너의 마음속에 품은 비전을 소중히 간직하고\n그것을 하나씩 현실로 만들어 가는 과정을 믿어봐요.  \n작은 한 걸음 한 걸음이 모여 결국 당신의 꿈이 눈앞에 펼쳐질 거예요.", source: "영화 소셜 네트워크 (2010)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "꿈을 향해 마음속에 그려본 모든 소망을 놓지 마세요.\n그리고 그 꿈을 현실로 만들기 위해 한 걸음씩 용기 있게 나아가 보세요.  \n당신의 작은 행동들이 결국 큰 변화를 만들어낼 거예요.", source: "영화 스티브 잡스 (2015)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "다른 것을 생각하는 마음에서\n진정한 성공이 시작됩니다.\n익숙한 길을 벗어나 새로운 시선을 품어보세요.", source: "영화 스티브 잡스 (2015)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "너의 일이 마음 깊이 사랑하는 무언가일 때,\n그때 비로소 진정한 성공이 찾아올 거예요.\n사랑하는 일을 할 때, 어려움도 기쁨으로 바뀌니까요.", source: "영화 스티브 잡스 (2015)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "완벽함을 향해 한 걸음씩 나아가세요.\n비록 완벽에 닿지 못하더라도,\n그 과정 속에서 진정한 성장과 아름다움을 발견할 수 있을 거예요.", source: "영화 스티브 잡스 (2015)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "너의 꿈은 언제나 너의 마음속에서 반짝이는 등불과 같아야 해요.\n그 빛을 따라 걸을 때, 비로소 진정한 너 자신을 만날 수 있으니까요.\n꿈이 너를 이끌어 줄 때, 삶은 더욱 빛나고 의미 있어질 거예요.", source: "영화 스티브 잡스 (2015)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "목표가 없으면 길을 잃기 쉽습니다.\n마음속에 작은 희망 하나라도 품고 걸어가면,\n어둠 속에서도 길을 찾을 수 있을 거예요.", source: "영화 포드 v 페라리 (2019)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "진정한 성취란 불가능해 보이는 일들을\n한 걸음 한 걸음 이루어 내는 데서 시작해요.\n포기하지 않고 도전하는 마음이 우리를 가능성의 문으로 이끌죠.", source: "영화 포드 v 페라리 (2019)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "팀 플레이는 혼자서는 이룰 수 없는 큰 성공을 만듭니다.\n서로의 힘을 모으고 마음을 하나로 모을 때,\n진정한 성과와 기쁨이 찾아오는 법이니까요.", source: "영화 포드 v 페라리 (2019)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "꿈은 크면 클수록 좋아요.\n그만큼 우리의 마음도 더 넓어지고,\n세상을 바라보는 눈도 깊어지니까요.", source: "영화 포드 v 페라리 (2019)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "목표를 향해 한 걸음 한 걸음 집중하는 마음이야말로\n진정한 성공의 씨앗이 됩니다.  \n그 집중력이 모여 우리를 더 큰 꿈 앞으로 이끌고,\n결국 원하는 결과를 이루게 해줍니다.", source: "영화 포드 v 페라리 (2019)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "꿈을 이루기 위해서는 때로 소중한 것들을 내려놓아야 해요.\n포기와 희생이 뒤따르지만, 그 과정이 있기에 진짜 원하는 꿈에 더 가까워질 수 있답니다.", source: "드라마 더 크라운 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "책임감은 우리 마음속 깊은 곳에서부터 힘을 길러줍니다.\n무거운 짐처럼 느껴질 때도 있지만,\n그것이야말로 진정한 강함의 씨앗이 되어줍니다.", source: "드라마 더 크라운 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "너에게 주어진 역할이 무엇이든,\n그 자리에서 최선을 다하는 것이 가장 소중한 일이에요.\n작은 책임이라도 충실히 해낼 때, 너의 빛나는 가치가 드러나니까요.", source: "드라마 더 크라운 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  { text: "의무는 우리가 스스로 선택하는 것이 아니라,\n마음 깊이 받아들여야 할 소중한 책임입니다.  \n그 책임을 다하는 과정에서 비로소 진정한 나를 만나게 되지요.", source: "드라마 더 크라운 (2016)", category: "꿈과 목표", type: "foreign-movie" },
  
  // 자신감과 용기
  { text: "너는 이미 충분히 좋은 사람이에요.\n그 누구와도 비교할 필요 없이,\n그 자체로 빛나는 존재임을 잊지 말아요.", source: "영화 라이온 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "자신을 믿는 마음은 가장 큰 힘이 되어줍니다.\n어떤 어려움이 와도 흔들리지 말고,\n당당하게 한 걸음씩 앞으로 나아가세요.", source: "영화 라이온 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 세상에 단 하나뿐인 소중한 존재예요.\n그 누구도 대신할 수 없는 너만의 빛과 가치가 있음을 꼭 기억하세요.  \n자신을 믿고 소중히 여길 때, 진정한 행복이 시작된답니다.", source: "영화 라이온 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "두려움은 결코 약함을 뜻하지 않아요.  \n오히려 그 두려움을 마주할 때 비로소 진정한 용기가 시작되는 법이니까요.  \n조금씩 떨리는 마음을 안고 한 걸음 내딛는 그 순간, 우리는 더 강해집니다.", source: "영화 라이온 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 혼자가 아니에요.\n어떤 순간에도 누군가가 곁에 있다는 것을 기억해 주세요.\n서로의 마음이 닿아 함께 걸어가는 길이니까요.", source: "영화 라이온 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "용기란 두려움이 전혀 없는 상태가 아니에요.\n오히려 두려움이 있을 때에도\n그 마음을 마주하고 이겨내는 힘을 말하는 거예요.", source: "영화 용감한 심장 (1995)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "자유는 우리 모두가 마음속 깊이 갈망하는 소중한 선물이에요.\n그 가치를 지키기 위해 때로는 용기 있게 맞서 싸워야 하죠.\n자유를 위해 한 걸음씩 나아가는 그 길이 바로 우리의 삶을 빛나게 합니다.", source: "영화 용감한 심장 (1995)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너만의 신념을 꼭 붙잡고 살아가세요.\n때로는 세상이 흔들려도 흔들리지 않는 마음이\n당신을 더욱 빛나게 만들어 줄 거예요.", source: "영화 용감한 심장 (1995)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "진정한 영웅은 두려움이 전혀 없는 사람이 아니에요.\n오히려 두려움을 마주하고도 그것을 이겨내는 사람이랍니다.\n그 용기 속에서 우리 모두가 배우고 성장하는 힘이 생겨나지요.", source: "영화 용감한 심장 (1995)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 언제나 너 자신이 되어야 할 가장 큰 영웅이에요.\n어떤 어려움이 와도 스스로를 믿고, 너만의 길을 당당히 걸어가길 바랍니다.", source: "영화 용감한 심장 (1995)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "자신감은 우리 마음속에 숨겨진 소중한 열쇠와 같아요.\n그 열쇠를 꼭 쥐고 있을 때, 비로소 성공의 문이 열리기 시작하죠.\n그러니 늘 자신을 믿고 한 걸음씩 나아가 보세요.", source: "영화 킹스 스피치 (2010)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 언제나 할 수 있는 힘을 지니고 있어요.\n어려움이 찾아와도 흔들리지 않고,\n그 속에서 더욱 단단해질 수 있는 충분한 강인함이 있답니다.", source: "영화 킹스 스피치 (2010)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "약점은 결코 부끄러운 것이 아니에요.\n그 안에 숨겨진 힘과 가능성을 발견한다면,\n그것이 바로 나만의 특별한 강점이 될 수 있답니다.", source: "영화 킹스 스피치 (2010)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너의 마음 깊은 곳에서 우러나오는 목소리를 꼭 내어 보아라.\n그 목소리가 세상에 닿을 때, 너만의 빛나는 이야기가 시작될 거야.", source: "영화 킹스 스피치 (2010)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "두려움을 한 걸음씩 마주할 때마다\n우리 마음속에 작은 용기가 자라나요.  \n그 용기가 쌓이고 쌓여 결국에는\n스스로를 믿는 큰 자신감으로 피어나게 됩니다.", source: "영화 킹스 스피치 (2010)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 이미 충분히 훌륭한 사람이에요.\n가끔은 스스로를 의심할 때도 있겠지만,\n그대로의 너를 사랑하고 믿어도 괜찮답니다.", source: "영화 굿 윌 헌팅 (1997)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너의 마음속 깊은 곳에 숨겨진 가능성을 믿어봐요.\n스스로를 향한 작은 믿음이 커다란 기적을 만들어낼 거예요.  \n그 믿음이 당신을 더 멀리, 더 높이 이끌어 줄 거예요.", source: "영화 굿 윌 헌팅 (1997)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "과거는 이미 지나간 시간일 뿐이에요.\n그 속에 머무르기보다는, 다가올 미래를 향해\n당신의 손으로 새로운 길을 만들어 가야 해요.", source: "영화 굿 윌 헌팅 (1997)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 결코 혼자가 아니에요.\n어두운 순간에도 누군가는 늘 당신을 믿고 응원하고 있답니다.\n그 믿음이 당신에게 큰 힘이 되어 줄 거예요.", source: "영화 굿 윌 헌팅 (1997)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너 자신을 사랑하는 일은 가장 소중한 시작이에요.\n내 안의 작은 빛을 발견하고 따뜻하게 감싸줄 때,\n비로소 진정한 행복이 찾아온답니다.", source: "영화 굿 윌 헌팅 (1997)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 세상에 단 하나뿐인 소중한 존재예요.\n그 어떤 누구와도 같지 않은 특별함을 품고 있기에,\n그 가치를 믿으며 당당하게 걸어가길 바랍니다.", source: "영화 더 쇼 (1998)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너의 진정한 자아를 숨기지 말고,\n있는 그대로 세상에 보여줘 보세요.\n그 속에서 진짜 나를 만나는 기쁨을 느낄 수 있을 거예요.", source: "영화 더 쇼 (1998)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "거짓 없이 살아가는 것은\n마음의 평화를 얻는 가장 소중한 길입니다.\n진실된 모습 그대로를 사랑하며 살아가세요.", source: "영화 더 쇼 (1998)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 세상 누구도 아닌 바로 너 자신이어야 해요.\n다른 사람의 모습에 맞추려 애쓰지 말고,\n진짜 너만의 빛을 세상에 보여주세요.", source: "영화 더 쇼 (1998)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "진정성은 마음 깊은 곳에서 우러나오는 힘이에요.\n그 진심이 모여서 결국 우리를 성공으로 이끌어 주지요.\n가장 빛나는 결과는 언제나 진실된 마음에서 시작된답니다.", source: "영화 더 쇼 (1998)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너는 이미 마음속 깊이 용기를 품고 있어요.\n때로는 자신을 믿는 그 작은 불씨가\n가장 큰 힘이 되어줄 거예요.", source: "드라마 스트레인저 씽스 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "함께라면 어떤 어려움도 두렵지 않아요.\n서로의 손을 잡고 마음을 나누면,\n그 어떤 시련도 우리를 넘어뜨릴 수 없답니다.", source: "드라마 스트레인저 씽스 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "너의 친구들은 너의 가장 든든한 버팀목이 되어줄 거예요.\n때로는 말없이 곁에 있어주며,\n진심으로 너를 이해하는 이들이니까요. 믿음을 주고받으며 함께 걸어가 보세요.", source: "드라마 스트레인저 씽스 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  { text: "용기는 혼자 있을 때보다\n누군가와 함께할 때 더 깊고 크게 자라납니다.\n서로의 손을 잡고 함께 나아갈 때, 두려움은 용기로 바뀌어요.", source: "드라마 스트레인저 씽스 (2016)", category: "자신감과 용기", type: "foreign-movie" },
  
  // 우정과 응원
  { text: "진정한 친구는 언제나 네 곁에 조용히 머물러 있어요.\n힘들 때나 기쁠 때나 변함없이 함께하며,\n그 존재만으로도 큰 위로가 되어준답니다.", source: "영화 토이 스토리 (1995)", category: "우정과 응원", type: "foreign-movie" },
  { text: "혼자가 아니에요.\n언제나 곁에 친구가 있어주니까요.\n그 마음만으로도 우리는 충분히 힘을 낼 수 있답니다.", source: "영화 토이 스토리 (1995)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구는 우리 삶에 스며든 소중한 가족과 같아요.  \n서로의 마음을 이해하고 의지하며  \n함께 걸어가는 따뜻한 존재이니까요.", source: "영화 토이 스토리 (1995)", category: "우정과 응원", type: "foreign-movie" },
  { text: "함께 손을 맞잡고 걸어간다면,\n어떤 어려움도 두렵지 않아요.\n서로의 힘이 되어주기에 모든 것이 가능하답니다.", source: "영화 토이 스토리 (1995)", category: "우정과 응원", type: "foreign-movie" },
  { text: "진심으로 너를 믿어주는 친구가 한 명만 있어도,  \n세상의 무거운 짐을 견뎌낼 힘이 생긴단다.  \n그 믿음 속에서 너는 언제나 든든한 버팀목을 느낄 수 있을 거야.", source: "영화 토이 스토리 (1995)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구는 우리의 모습을 비추는 소중한 거울과 같아요.\n그들이 보여주는 모습 속에서 나 자신을 돌아보고,\n더 나은 사람이 되기 위한 힘을 얻을 수 있답니다.", source: "영화 포레스트 검프 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "진정한 친구란 시간이 흘러도 변하지 않고,\n그 마음이 늘 우리 곁에 머무는 사람입니다.\n그래서 진정한 우정은 영원히 빛나고 소중한 선물이 되어줍니다.", source: "영화 포레스트 검프 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구와 함께 나눈 소중한 추억들은 시간이 지나도 마음속에 따뜻하게 남아 있어요.\n그 순간들이 모여 우리의 삶을 더욱 풍요롭고 의미 있게 만들어 주지요.\n그래서 친구와의 기억은 무엇과도 바꿀 수 없는 귀한 보물과 같답니다.", source: "영화 포레스트 검프 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구는 인생의 소중한 보물과 같아요.\n어떤 어려움이 와도 그 손을 놓지 말고,\n진심으로 마음을 나누는 친구를 꼭 지켜가세요.", source: "영화 포레스트 검프 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구는 우리 삶에 깊은 영향을 주는 소중한 존재예요.  \n그들은 때로는 조용한 힘이 되어주고,  \n우리의 인생을 새로운 방향으로 이끌어 주기도 하지요.", source: "영화 포레스트 검프 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "함께 웃을 때 우리는 기쁨을 두 배로 나누고,\n함께 울 때는 슬픔을 반으로 줄일 수 있어요.\n서로의 마음을 나누며 진정한 위로가 되는 그런 사람이 되어주세요.", source: "영화 라이프 이즈 뷰티풀 (1997)", category: "우정과 응원", type: "foreign-movie" },
  { text: "사랑하는 사람들과 함께하는 시간은 가장 소중한 선물이에요.\n서로의 온기를 느끼며 마음을 나누는 그 순간들이\n우리 인생을 더욱 빛나게 만들어 준답니다.", source: "영화 라이프 이즈 뷰티풀 (1997)", category: "우정과 응원", type: "foreign-movie" },
  { text: "가장 소중한 것은 언제나 우리 곁에 있는 가족과 친구라는 존재입니다.\n그들의 따뜻한 마음과 함께하는 순간들이야말로 삶의 진정한 보물이지요.\n서로를 아끼고 사랑하며 나누는 시간 속에서 행복이 자라납니다.", source: "영화 라이프 이즈 뷰티풀 (1997)", category: "우정과 응원", type: "foreign-movie" },
  { text: "함께하는 시간은 우리에게 가장 소중한 선물이에요.\n서로의 마음이 맞닿아 따뜻함이 피어나는 그 순간이야말로,\n진정한 아름다움으로 가득한 시간이랍니다.", source: "영화 라이프 이즈 뷰티풀 (1997)", category: "우정과 응원", type: "foreign-movie" },
  { text: "언제나 너의 곁에는\n조용히 응원해주는 사람이 있어요.\n그 마음을 기억하며 힘내길 바랄게요.", source: "영화 라이프 이즈 뷰티풀 (1997)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구의 따뜻한 응원은 우리 마음에 깊은 힘이 되어줍니다.\n어려운 순간에도 그 한마디가 큰 용기와 희망으로 다가와,\n다시 일어설 수 있는 원동력이 되어주지요.", source: "영화 8 마일 (2002)", category: "우정과 응원", type: "foreign-movie" },
  { text: "혼자가 아니라는 것을 기억하세요.\n어떤 어려움이 찾아와도,\n당신 곁에는 항상 누군가가 함께하고 있다는 사실을 잊지 마세요.", source: "영화 8 마일 (2002)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구는 인생에서 가장 소중한 보물과 같아요.\n어려울 때 곁에 있어 주고, 함께 웃을 수 있는 사람은 무엇과도 바꿀 수 없는 큰 자산이랍니다. \n서로를 지켜주고 힘이 되어 주는 친구가 있기에 우리의 삶은 더욱 풍요로워져요.", source: "영화 8 마일 (2002)", category: "우정과 응원", type: "foreign-movie" },
  { text: "함께 손을 맞잡고 걸을 때,\n우리는 혼자일 때보다 훨씬 더 큰 힘을 낼 수 있어요.\n서로를 믿고 의지할 때, 그 힘은 무한히 커지니까요.", source: "영화 8 마일 (2002)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구가 너를 믿어줄 때, 그 믿음은 너에게 큰 힘이 되어줘요.\n혼자일 때보다 더 용기 내고, 어려움도 함께 이겨낼 수 있답니다.  \n그 믿음 속에서 너는 더욱 단단해지고,\n세상을 향해 당당히 나아갈 수 있어요.", source: "영화 8 마일 (2002)", category: "우정과 응원", type: "foreign-movie" },
  { text: "세상 어딘가에는 언제나 너를 응원하고 지지하는 사람들이 있어요.\n힘들 때 그들의 따뜻한 마음을 떠올리며,\n혼자가 아니라는 걸 기억해 주세요.", source: "영화 더 펄스 (2006)", category: "우정과 응원", type: "foreign-movie" },
  { text: "함께라면 세상의 어떤 어려움도 견딜 수 있어요.\n서로의 손을 꼭 잡고 있기에, 두려움조차 멀리 사라진답니다.\n함께라서 우리는 언제나 든든하고 안전해요.", source: "영화 더 펄스 (2006)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구는 언제나 네 곁에서 힘이 되어 주는 소중한 존재예요.\n어려울 때 함께 울어주고, 기쁠 때 함께 웃어주는 그들이 있기에\n우리는 더욱 용기 내어 나아갈 수 있답니다.", source: "영화 더 펄스 (2006)", category: "우정과 응원", type: "foreign-movie" },
  { text: "함께 나누는 기쁨은 혼자 느끼는 기쁨보다 훨씬 더 깊고 따뜻해요.\n서로의 마음이 닿을 때 비로소 진정한 행복이 완성되기 때문이죠.\n그래서 우리는 기쁨을 나누며 더욱 풍요로운 삶을 살아가게 됩니다.", source: "영화 더 펄스 (2006)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구의 따뜻한 응원 없이는 진정한 성공을 이루기 어렵습니다.\n서로가 서로의 힘이 되어주기에, 그 길이 더욱 빛나고 의미 있어지는 법이니까요.", source: "드라마 프렌즈 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구는 우리의 삶 속에서 특별한 가족과 같아요.\n서로를 이해하고 지지하며,\n때로는 가장 가까운 이가 되어주니까요.", source: "드라마 프렌즈 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "함께 웃을 때 비로소 마음이 따뜻해지고,\n서로의 곁에서 함께 성장할 때 진정한 행복이 찾아와요.\n우리의 이야기는 그렇게 조금씩 더 아름다워져 가는 거예요.", source: "드라마 프렌즈 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "친구와 함께하는 시간은 세상 그 무엇보다도 소중해요.  \n서로의 이야기를 나누고, 웃음과 위로를 주고받는 그 순간들이  \n우리 마음 깊은 곳에 따뜻한 기억으로 남기 때문이죠.", source: "드라마 프렌즈 (1994)", category: "우정과 응원", type: "foreign-movie" },
  { text: "너는 결코 혼자가 아니에요.\n언제나 곁에는 당신을 응원하는 친구들이 함께 있어요.\n서로의 마음을 나누며 힘이 되어 줄 거예요.", source: "드라마 프렌즈 (1994)", category: "우정과 응원", type: "foreign-movie" },

  // ========== 해외 유명 저자·명사 명언 (300개) ==========
  
  // 공부와 노력
  { text: "성공은 단순한 우연이 아니에요.\n꾸준한 준비와 그때 찾아오는 기회가 만나야 비로소 이루어지죠.\n그래서 매 순간 최선을 다하는 당신의 노력이 가장 소중합니다.", source: "스티브 잡스", category: "공부와 노력", type: "foreign-author" },
  { text: "너의 시간은 한정되어 있기에 소중해요.\n그러니 다른 사람의 기대나 삶에 얽매이지 말고,\n진정으로 너만의 길을 걸어가길 바랄게요.", source: "스티브 잡스", category: "공부와 노력", type: "foreign-author" },
  { text: "완벽함을 향한 작은 노력이 모여서\n비로소 좋은 결과를 만들어 냅니다.\n완벽을 꿈꾸지 않는다면, 그 아름다운 결실도 만나기 어렵습니다.", source: "스티브 잡스", category: "공부와 노력", type: "foreign-author" },
  { text: "혁신은 단지 한 순간의 반짝임이 아니라,  \n작은 영감 1%와 그보다 훨씬 큰 99%의 끊임없는 노력이 모여 이루어집니다.  \n진정한 변화는 꾸준한 열정과 인내 속에서 피어나는 법이지요.", source: "토마스 에디슨", category: "공부와 노력", type: "foreign-author" },
  { text: "천재라는 것은 단지 순간의 번뜩임만으로 이루어지지 않아요.\n작은 영감 한 조각이 불씨가 되어도,\n그 뒤에는 끊임없는 노력과 땀방울이 가득해야 비로소 빛날 수 있답니다.", source: "토마스 에디슨", category: "공부와 노력", type: "foreign-author" },
  { text: "실패는 결코 끝이 아니에요.\n오히려 더 나은 성공을 품은 따뜻한 어머니와 같아서,\n우리가 다시 일어나 앞으로 나아가도록 힘을 줍니다.", source: "토마스 에디슨", category: "공부와 노력", type: "foreign-author" },
  { text: "나는 실패한 것이 아니에요.\n그저 원하는 결과를 얻기 위해서\n작동하지 않는 수많은 방법들을 발견했을 뿐이죠.  \n그 과정 속에서 배움이 쌓이고,\n마침내 성공에 한 걸음 더 가까워진 거랍니다.", source: "토마스 에디슨", category: "공부와 노력", type: "foreign-author" },
  { text: "성공은 우리가 향해 나아가는 소중한 목표일 뿐,\n결코 최종 목적지가 아니에요.  \n그 과정 속에서 배우고 성장하는 순간들이야말로\n진정한 의미를 만들어 가는 시간이니까요.", source: "빌 게이츠", category: "공부와 노력", type: "foreign-author" },
  { text: "열심히 일하는 마음은\n자신을 성장시키는 가장 소중한 씨앗이에요.  \n그리고 멈추지 않고 배우는 자세가 있다면,\n그 씨앗은 어느새 풍성한 열매를 맺을 거예요.", source: "빌 게이츠", category: "공부와 노력", type: "foreign-author" },
  { text: "교육은 우리 삶의 가장 소중한 밑거름이에요.\n오늘 배우는 모든 것이 모여서\n밝고 희망찬 미래를 만들어 가니까요.", source: "빌 게이츠", category: "공부와 노력", type: "foreign-author" },
  { text: "노력 없이는 진정한 성공을 이룰 수 없어요.\n작은 한 걸음 한 걸음이 모여서\n마침내 빛나는 결실을 만들어 내니까요.", source: "빌 게이츠", category: "공부와 노력", type: "foreign-author" },
  { text: "계속해서 배우지 않으면\n세상은 점점 더 빠르게 변하고,\n우리는 어느새 뒤처지고 말아요.  \n배움은 멈추지 않는 여정이기에,\n그 속에서 성장하며 나아갈 수 있답니다.", source: "빌 게이츠", category: "공부와 노력", type: "foreign-author" },
  { text: "성공은 언제나 실패라는 작은 씨앗에서 자라납니다.\n넘어지고 다시 일어서는 그 과정 속에서 우리는 진정한 성장을 경험하죠.\n그래서 실패조차도 우리를 더 단단하게 만들어주는 소중한 친구입니다.", source: "오프라 윈프리", category: "공부와 노력", type: "foreign-author" },
  { text: "언제나 너 자신 안에 숨겨진 가장 빛나는 모습을 찾아서\n그 누구도 아닌 너만의 최고의 버전으로 자라가길 바래.\n네가 가진 가능성은 무한하니까, 그 길을 믿고 걸어가렴.", source: "오프라 윈프리", category: "공부와 노력", type: "foreign-author" },
  { text: "노력은 결코 우리를 실망시키지 않아요.\n꾸준히 마음을 다해 쌓아 올린 작은 발걸음들이\n언젠가 반드시 빛나는 결실로 돌아오니까요.", source: "오프라 윈프리", category: "공부와 노력", type: "foreign-author" },
  { text: "성공은 멈추지 않고 한 걸음씩 나아가는 데 있어요.\n때로는 힘들고 지칠 때도 있겠지만,\n그 꾸준함이 결국 우리를 원하는 곳으로 이끌어 줄 거예요.", source: "오프라 윈프리", category: "공부와 노력", type: "foreign-author" },
  { text: "너는 지금 이 순간에도 충분히 잘하고 있어요.\n때로는 스스로를 믿기 어려울 때도 있지만,\n그 모든 과정이 너를 더욱 빛나게 만들고 있답니다.", source: "오프라 윈프리", category: "공부와 노력", type: "foreign-author" },
  { text: "성공은 한순간의 결과가 아니라,\n매일 쌓아가는 작은 습관들의 모임이에요.\n꾸준함이 쌓여서 비로소 큰 꿈이 이루어지죠.", source: "아리스토텔레스", category: "공부와 노력", type: "foreign-author" },
  { text: "우리는 매일의 작은 선택과 행동들이 모여 만들어진 존재예요.\n결국, 우리가 반복하는 것들이 바로 우리 자신이 되기 때문이죠.\n그러니 오늘도 좋은 습관을 쌓아가며 나답게 살아가 보아요.", source: "아리스토텔레스", category: "공부와 노력", type: "foreign-author" },
  { text: "탁월함은 단순히 한 번의 멋진 행동이 아니라\n매일매일 꾸준히 쌓아가는 작은 습관에서 비롯됩니다.\n우리의 일상이 모여 결국 빛나는 결과를 만들어내는 거예요.", source: "아리스토텔레스", category: "공부와 노력", type: "foreign-author" },
  { text: "작은 노력 하나하나가 모여서\n언젠가는 큰 변화를 만들어 냅니다.\n꾸준히 걸어가는 그 발걸음이 결국은 큰 결실이 되지요.", source: "아리스토텔레스", category: "공부와 노력", type: "foreign-author" },
  { text: "습관은 우리의 하루하루를 만들어가고,\n그 작은 반복들이 모여 결국 인생의 큰 그림을 그려줍니다.\n그래서 어떤 습관을 가지느냐가 곧 우리의 미래를 결정짓는 중요한 열쇠가 됩니다.", source: "아리스토텔레스", category: "공부와 노력", type: "foreign-author" },
  { text: "성공은 하루아침에 찾아오지 않아요.\n작은 노력들이 쌓이고 쌓여서야 비로소 그 결실을 맺는답니다.\n조금씩 천천히, 꾸준히 나아가는 그 과정도 소중히 여기세요.", source: "마크 저커버그", category: "공부와 노력", type: "foreign-author" },
  { text: "계속해서 배우고 성장하는 것은 우리 삶의 아름다운 여정입니다.\n매일 조금씩 나아가며 스스로를 더 깊이 이해하고,\n새로운 가능성으로 가득한 내일을 맞이해 보세요.", source: "마크 저커버그", category: "공부와 노력", type: "foreign-author" },
  { text: "작은 시작이 모여서 결국 큰 변화를 만듭니다.\n처음 한 걸음이 작아 보여도, 그 한 걸음이 쌓여서\n언젠가는 멋진 결실을 이루게 될 거예요.", source: "마크 저커버그", category: "공부와 노력", type: "foreign-author" },
  { text: "실패를 두려워하지 말아요.\n그것은 우리가 성장하는 과정의 일부니까요.\n넘어져도 다시 일어서며 더 강해질 수 있답니다.", source: "마크 저커버그", category: "공부와 노력", type: "foreign-author" },
  { text: "노력은 작은 씨앗과 같아요.\n꾸준히 가꾸고 기다리면,\n언젠가 반드시 아름다운 꽃을 피울 수 있답니다.", source: "마크 저커버그", category: "공부와 노력", type: "foreign-author" },
  { text: "성공은 어느 날 갑자기 찾아오는 행운이 아니에요.\n꾸준히 마음을 다해 준비해 온 사람의 곁에 살며시 다가오는 선물과 같답니다.\n그래서 오늘도 한 걸음씩 성실히 나아가는 당신이 결국 빛나는 결실을 맞이하게 될 거예요.", source: "벤저민 프랭클린", category: "공부와 노력", type: "foreign-author" },
  { text: "계획이 없이 시작하면 실패할 가능성이 커져요.\n작은 준비와 마음가짐이 큰 차이를 만들어내니까,\n조금은 천천히, 차근차근 길을 그려보는 것이 중요해요.", source: "벤저민 프랭클린", category: "공부와 노력", type: "foreign-author" },
  { text: "오늘 내가 흘린 작은 땀방울 하나하나가\n내일의 빛나는 성공을 만드는 밑거름이 됩니다.\n꾸준한 오늘의 노력이 모여서 결국 꿈을 현실로 만들어 주니까요.", source: "벤저민 프랭클린", category: "공부와 노력", type: "foreign-author" },
  { text: "시간은 돈과도 같아서,\n한 번 지나가면 다시 돌려받을 수 없어요.\n소중히 여기고 현명하게 써야 하는 이유입니다.", source: "벤저민 프랭클린", category: "공부와 노력", type: "foreign-author" },
  
  // 극복과 도전
  { text: "불가능한 일은 세상에 없어요.\n그저 아직 그 길을 걷기 시작하지 않았을 뿐이죠.\n조금만 용기를 내어 첫걸음을 내딛는다면,\n언젠가 그 꿈도 현실이 될 거예요.", source: "넬슨 만델라", category: "극복과 도전", type: "foreign-author" },
  { text: "나는 언제나 승리하거나 배움을 얻어요.  \n진정한 패배란 없기에, 넘어져도 다시 일어나며  \n더 강해지는 나 자신을 발견하곤 하죠.", source: "넬슨 만델라", category: "극복과 도전", type: "foreign-author" },
  { text: "용기란 두려움이 전혀 없는 상태가 아니에요.\n진짜 용기는 마음속에 있는 두려움을 마주하고,\n조금씩 이겨내며 앞으로 나아가는 힘을 뜻한답니다.", source: "넬슨 만델라", category: "극복과 도전", type: "foreign-author" },
  { text: "어둠이 깊어질수록 그 안에서 빛을 찾아야 해요.\n작은 빛 한 줄기가 희망이 되어\n우리 마음을 따뜻하게 비춰줄 거예요.", source: "넬슨 만델라", category: "극복과 도전", type: "foreign-author" },
  { text: "절대 포기하지 말아요.\n어떤 어려움이 와도 마음을 굳게 먹고,\n끝까지 자신의 길을 믿으며 나아가야 해요.", source: "넬슨 만델라", category: "극복과 도전", type: "foreign-author" },
  { text: "고통이 없으면 성장도 없어요.\n힘든 순간들이 우리를 단단하게 만들고,\n그 경험들이 결국 더 나은 나로 자라게 해주니까요.", source: "프리드리히 니체", category: "극복과 도전", type: "foreign-author" },
  { text: "무엇이 너를 죽이지 못한다면,\n그것은 결국 너를 더 강하게 만드는 법이야.\n힘들고 어려운 순간들이 쌓여서,\n너의 내면에 단단한 힘을 키워주니까.", source: "프리드리히 니체", category: "극복과 도전", type: "foreign-author" },
  { text: "너는 생각하는 것보다 훨씬 더 강한 사람이에요.\n어려운 순간에도 마음속 깊은 곳에서 힘이 샘솟는다는 걸 잊지 마세요.\n스스로를 믿으면 어떤 어려움도 이겨낼 수 있을 거예요.", source: "프리드리히 니체", category: "극복과 도전", type: "foreign-author" },
  { text: "고통은 결코 우리가 약하다는 표시가 아니에요.\n오히려 그것은 우리 안에 숨겨진 강인함과 성장의 씨앗이 자라고 있다는 신호랍니다.\n힘들고 아플 때마다, 그 순간이 더 단단해질 기회임을 기억해 주세요.", source: "프리드리히 니체", category: "극복과 도전", type: "foreign-author" },
  { text: "우리는 스스로의 한계를 제대로 알지 못해요.\n그것이 때로는 두렵기도 하지만,\n그래서 더 멀리 나아갈 수 있는 힘이 되기도 한답니다.", source: "프리드리히 니체", category: "극복과 도전", type: "foreign-author" },
  { text: "실패는 우리가 성공으로 나아가는 길목에 놓인 소중한 첫걸음이에요.\n넘어지고 다시 일어서는 그 과정 속에서 비로소 진짜 성장이 시작되니까요.  \n모든 위대한 도전 뒤에는 실패가 숨어 있지만, 그것이 바로 성공의 문을 여는 열쇠가 된답니다.", source: "톰 워터스", category: "극복과 도전", type: "foreign-author" },
  { text: "계속해서 한 걸음 한 걸음 나아가다 보면,\n비록 느릴지라도 결국에는 원하는 성공에 닿게 됩니다.\n포기하지 않는 마음이 가장 큰 힘이 되어줄 거예요.", source: "톰 워터스", category: "극복과 도전", type: "foreign-author" },
  { text: "절대 포기하지 말아요.  \n어떤 어려움이 와도 마음속 깊이 단단히 붙잡으세요.  \n끝까지 포기하지 않는 그 마음이 결국 빛나는 기적을 만들어낼 거예요.", source: "톰 워터스", category: "극복과 도전", type: "foreign-author" },
  { text: "위기는 우리에게 찾아오는 뜻밖의 순간이에요.\n그 안에는 어려움뿐만 아니라 성장할 수 있는 소중한 기회가 숨어 있답니다.\n그러니 두려워 말고, 그 순간을 용기 있게 마주해 보세요.", source: "톰 워터스", category: "극복과 도전", type: "foreign-author" },
  { text: "너는 이미 많은 어려움을 이겨내며 자라왔기에\n그 어떤 시련도 충분히 견뎌낼 힘이 있어요.\n스스로를 믿고 천천히 앞으로 나아가면 돼요.", source: "톰 워터스", category: "극복과 도전", type: "foreign-author" },
  { text: "도전이 없이는 진정한 성장을 기대할 수 없어요.\n새로운 길에 용기내어 나설 때마다,\n우리는 조금씩 더 나은 자신으로 거듭나게 됩니다.", source: "조지 버나드 쇼", category: "극복과 도전", type: "foreign-author" },
  { text: "성공이란 불가능해 보이는 일들을\n포기하지 않고 계속 도전하며 이루어내는 것입니다.\n그 과정에서 우리는 스스로의 한계를 넘어설 수 있지요.", source: "조지 버나드 쇼", category: "극복과 도전", type: "foreign-author" },
  { text: "진정한 영웅이란 멀리서 빛나는 존재가 아니라,\n스스로의 약한 마음과 두려움을 넘어서는 사람입니다.\n자신을 이겨내는 그 과정 속에서 진정한 용기와 힘이 자라납니다.", source: "조지 버나드 쇼", category: "극복과 도전", type: "foreign-author" },
  { text: "고통은 우리를 시험하지만,\n그 안에서 우리는 진정한 강함을 발견하게 됩니다.\n어려움 속에서 피어나는 힘은 우리를 더욱 단단하게 만들어 줍니다.", source: "조지 버나드 쇼", category: "극복과 도전", type: "foreign-author" },
  { text: "너는 어디에 있든지 스스로의 길을 만들어 가는 사람이에요.\n운명은 정해진 것이 아니라, 당신이 선택하고 노력하는 만큼 달라질 수 있답니다.\n그러니 매 순간 자신을 믿고 한 걸음씩 나아가 보세요.", source: "조지 버나드 쇼", category: "극복과 도전", type: "foreign-author" },
  { text: "실패는 성공의 반대말이 아니라,\n성공으로 가는 길에 반드시 거쳐야 할 소중한 과정이에요.  \n때로는 넘어지고 좌절할지라도,\n그 모든 경험이 결국 더 큰 성취를 만들어 줍니다.", source: "J.K. 롤링", category: "극복과 도전", type: "foreign-author" },
  { text: "절대 포기하지 말아요.\n어떤 어려움이 와도 마음을 굳게 먹고,\n끝까지 희망을 품고 나아가는 것이 진정한 용기랍니다.", source: "J.K. 롤링", category: "극복과 도전", type: "foreign-author" },
  { text: "너는 스스로 생각하는 것보다 훨씬 더 강한 사람이에요.\n어려움 속에서도 포기하지 않고 버텨내는 그 힘이 바로 너의 진짜 모습이니까요.  \n언제나 자신을 믿고 앞으로 나아가길 바랍니다.", source: "J.K. 롤링", category: "극복과 도전", type: "foreign-author" },
  { text: "고통은 잠시 찾아와 우리를 시험하지만,\n그 시간이 지나면 반드시 사라져요.  \n반면에 그 고통을 통해 얻은 성장과 배움은\n우리 마음속에 깊이 새겨져 영원히 남는답니다.", source: "J.K. 롤링", category: "극복과 도전", type: "foreign-author" },
  { text: "너의 한계를 넘어서는 순간,\n비로소 새로운 세상이 열릴 거예요.\n조금은 두렵더라도, 그 너머의 가능성을 믿어 보세요.", source: "J.K. 롤링", category: "극복과 도전", type: "foreign-author" },
  { text: "도전하지 않는다면,\n성공이라는 열매도 결코 맛볼 수 없어요.\n용기를 내어 한 걸음 내딛는 그 순간이 바로,\n당신의 꿈을 향한 첫 번째 시작이니까요.", source: "무하마드 알리", category: "극복과 도전", type: "foreign-author" },
  { text: "나는 할 수 있다는 믿음을 마음에 품고 있어요.\n그 믿음이 나를 앞으로 나아가게 하며,\n나는 반드시 해낼 거예요.", source: "무하마드 알리", category: "극복과 도전", type: "foreign-author" },
  { text: "두려움은 결코 약함이 아니에요.\n오히려 그것은 우리 마음이 얼마나 깊고 진실한지를 보여주는 증거랍니다.\n두려움을 마주할 때, 우리는 한층 더 강해지고 성장하는 법을 배우게 되니까요.", source: "무하마드 알리", category: "극복과 도전", type: "foreign-author" },
  { text: "진정한 승리는 멈추지 않고 앞으로 나아가는 데 있어요.\n비록 길이 험하고 힘들지라도,\n한 걸음 한 걸음 꾸준히 나아가는 그 마음이 결국 승리를 만듭니다.", source: "무하마드 알리", category: "극복과 도전", type: "foreign-author" },
  
  // 꿈과 목표
  { text: "큰 꿈을 품고 살아가세요.  \n그 꿈은 여러분의 마음속에 밝은 빛이 되어  \n어둠 속에서도 길을 잃지 않게 도와줄 거예요.", source: "월트 디즈니", category: "꿈과 목표", type: "foreign-author" },
  { text: "꿈을 꾸는 것은 우리 마음의 작은 불꽃과 같아요.\n그 불꽃을 지키고 키우기 위해서는 반드시 행동으로 옮겨야 합니다.\n꿈을 꾸고 실행할 때, 비로소 그 소망은 현실로 다가오게 됩니다.", source: "월트 디즈니", category: "꿈과 목표", type: "foreign-author" },
  { text: "너의 꿈은 단순한 바람이 아니에요.\n그 꿈이 바로 너라는 사람을 만들어가고,\n너만의 이야기를 써 내려가는 힘이 되어줘요.", source: "월트 디즈니", category: "꿈과 목표", type: "foreign-author" },
  { text: "꿈은 단순한 바람에 그치지 않아요.\n꾸준한 노력과 믿음이 함께할 때,\n비로소 현실로 다가올 수 있답니다.", source: "월트 디즈니", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표가 없으면 길을 잃고 헤매기 쉽습니다.\n그래서 우리는 작은 꿈이라도 품고 나아가야 해요.\n그 길 위에서 비로소 자신만의 길을 발견할 수 있으니까요.", source: "월트 디즈니", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표를 향해 한 걸음씩 꾸준히 나아가세요.\n비록 길이 멀고 험난할지라도,\n그 여정 속에서 당신은 더욱 빛나게 될 거예요.", source: "스티브 잡스", category: "꿈과 목표", type: "foreign-author" },
  { text: "너의 꿈은 너만의 소중한 별과 같아,\n어두운 밤하늘 속에서도 반짝이며 너를 이끌어 줄 거야.\n그러니 절대 그 빛을 놓지 말고 끝까지 붙잡아야 해.", source: "스티브 잡스", category: "꿈과 목표", type: "foreign-author" },
  { text: "작은 생각으로는 결코 큰 변화를 만들어낼 수 없어요.\n마음속에 품은 꿈과 아이디어가 클수록,\n우리는 더 멀리 나아가고 더 큰 세상을 만날 수 있답니다.", source: "스티브 잡스", category: "꿈과 목표", type: "foreign-author" },
  { text: "너만의 소중한 비전을 마음속에 품고\n그것을 현실로 만들어 가는 여정은\n세상에서 가장 값진 모험이 될 거예요.  \n작은 한 걸음 한 걸음이 쌓여\n당신의 꿈이 눈앞에 펼쳐질 테니까요.", source: "스티브 잡스", category: "꿈과 목표", type: "foreign-author" },
  { text: "꿈을 이루는 길은 결코 쉽지 않아요.\n수많은 어려움과 시련이 우리를 기다리지만,\n그래도 그 꿈은 충분히 이루어질 수 있다는 희망이 있습니다.", source: "스티브 잡스", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표는 분명해야 해요.\n그래야만 흔들리지 않고 한 걸음씩 나아갈 수 있으니까요.\n마음속에 뚜렷한 길이 있을 때, 우리는 더 자신 있게 꿈을 향해 걸어갈 수 있답니다.", source: "피터 드러커", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표 없이 무작정 행동하는 것은 마치 나침반 없는 배와 같아요.\n방향을 잃고 헤매다 보면 결국 원하는 곳에 닿기 어렵기 마련이죠.\n그래서 작은 목표라도 세우고 한 걸음씩 나아가는 것이 중요해요.", source: "피터 드러커", category: "꿈과 목표", type: "foreign-author" },
  { text: "계획이 없이 시작한다는 것은,\n어쩌면 실패를 향해 스스로 길을 닦는 것과 같아요.\n그러니 작은 목표라도 세워서,\n한 걸음씩 나아가는 것이 우리를 지켜주는 힘이 된답니다.", source: "피터 드러커", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표를 이루기 위해서는 온 마음을 다해 집중하는 것이 필요해요.\n한 걸음 한 걸음, 흔들리지 않는 마음으로 나아갈 때 비로소 꿈에 닿을 수 있답니다.  \n작은 방해에도 마음이 흐트러지지 않도록\n스스로를 다잡는 힘이 중요해요.", source: "피터 드러커", category: "꿈과 목표", type: "foreign-author" },
  { text: "성공이란 단순히 결과만을 뜻하지 않아요.\n진정한 성공은 자신이 세운 목표를 향해 한 걸음씩 나아가며,\n마침내 그 목표를 이루었을 때 느끼는 깊은 만족감이랍니다.", source: "피터 드러커", category: "꿈과 목표", type: "foreign-author" },
  { text: "꿈을 이루기 위해서는 때로 소중한 것들을 내려놓아야 해요.\n희생이라는 작은 불편함이 쌓여서야 비로소 큰 기쁨으로 돌아오니까요.\n그 길 위에서 우리는 진정한 성장과 의미를 발견하게 될 거예요.", source: "오프라 윈프리", category: "꿈과 목표", type: "foreign-author" },
  { text: "너의 목표를 분명하게 세워 보세요.\n그렇게 하면 길이 더욱 뚜렷해지고,\n마음속 불안도 조금씩 사라질 거예요.", source: "오프라 윈프리", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표를 향해 천천히라도 한 걸음씩 나아가 보세요.\n작은 발걸음들이 모여 결국 큰 꿈을 이루는 법이니까요.\n조금씩 전진하는 당신의 모습이 가장 아름답답니다.", source: "오프라 윈프리", category: "꿈과 목표", type: "foreign-author" },
  { text: "꿈은 크면 클수록 좋습니다.\n그 큰 꿈이 우리 마음속에 불을 지피고,\n하루하루를 특별하게 만들어 주니까요.", source: "오프라 윈프리", category: "꿈과 목표", type: "foreign-author" },
  { text: "너의 마음속 깊이 간직한 꿈이\n항상 너의 길을 밝혀주는 등불이 되어야 해요.\n그 꿈이 너를 부드럽게 이끌며,\n어디로 가야 할지 잃지 않도록 도와줄 거예요.", source: "오프라 윈프리", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표를 향해 한 걸음 한 걸음 꾸준히 나아가는 집중력이야말로\n진정한 성공의 밑거름이 되어줍니다. 흔들림 없이 마음을 모을 때,\n비로소 꿈꾸던 그 자리까지 닿을 수 있음을 잊지 마세요.", source: "짐 론", category: "꿈과 목표", type: "foreign-author" },
  { text: "꿈을 꾸는 것은 우리 마음속에 빛을 켜는 일이에요.\n그 빛을 따라 한 걸음씩 행동할 때, 비로소 꿈은 현실이 된답니다.  \n꿈을 품고 그 길을 향해 용기 있게 나아가 보세요.", source: "짐 론", category: "꿈과 목표", type: "foreign-author" },
  { text: "성공은 단순한 행운이 아니에요.\n꾸준히 준비하고 노력하는 사람에게만\n그 문이 조용히 열리는 법이니까요.", source: "짐 론", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표가 없으면 성공도 없어요.  \n우리가 어디로 가야 할지 모르는데  \n그 길에서 빛나는 성취를 만날 수는 없으니까요.", source: "짐 론", category: "꿈과 목표", type: "foreign-author" },
  { text: "너의 목표를 매일 마음속에 품고 살아가 보세요.\n작은 하루하루의 생각들이 모여 결국 큰 꿈을 이루는 밑거름이 될 테니까요.\n그렇게 꾸준히 자신을 다독이며 나아가는 길이 진정한 성장의 시작입니다.", source: "짐 론", category: "꿈과 목표", type: "foreign-author" },
  { text: "꿈은 멀리 있는 별처럼 보일지 몰라요.\n하지만 포기하지 않고 꾸준히 노력한다면,\n언젠가는 그 빛나는 별을 손에 넣을 수 있을 거예요.", source: "조셉 머피", category: "꿈과 목표", type: "foreign-author" },
  { text: "너의 마음속에 담긴 생각과 감정이\n결국 너의 세상을 만들어간단다.\n그러니 늘 따뜻하고 긍정적인 마음으로\n네 현실을 아름답게 빚어가길 바란다.", source: "조셉 머피", category: "꿈과 목표", type: "foreign-author" },
  { text: "목표를 향해 한 걸음씩 나아가세요.\n비록 길이 멀고 험해도,\n스스로를 믿는 마음이 가장 큰 힘이 되어줄 거예요.", source: "조셉 머피", category: "꿈과 목표", type: "foreign-author" },
  { text: "너는 네가 품고 있는 생각 그 자체예요.\n마음속에 무엇을 담느냐에 따라\n너의 하루와 삶이 달라질 거예요.", source: "조셉 머피", category: "꿈과 목표", type: "foreign-author" },
  
  // 자신감과 용기
  { text: "너는 그 자체로 이미 충분히 아름답고 소중한 존재예요.\n세상이 아무리 변해도, 너의 가치는 변하지 않으니\n스스로를 믿고 사랑하는 마음을 잃지 않았으면 해요.", source: "브레네 브라운", category: "자신감과 용기", type: "foreign-author" },
  { text: "자신을 믿는 마음은 가장 든든한 힘이 되어줍니다.\n어떤 어려움이 와도 두려워 말고,\n한 걸음 한 걸음 앞으로 나아가 보세요.", source: "브레네 브라운", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 세상에 단 하나뿐인 소중한 존재입니다.\n스스로의 가치를 잊지 말고,\n자신을 사랑하는 마음으로 하루하루를 살아가길 바랍니다.", source: "브레네 브라운", category: "자신감과 용기", type: "foreign-author" },
  { text: "취약함은 결코 약함이 아니에요.\n오히려 그 속에는 진정한 용기와 강인함이 숨겨져 있답니다.\n자신의 부족함을 인정하는 순간, 우리는 더욱 깊게 성장할 수 있어요.", source: "브레네 브라운", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 이미 이 세상에 꼭 필요한 존재예요.\n때로는 스스로를 의심할지라도,\n그 마음 속 깊이 숨겨진 훌륭함을 잊지 말아요.", source: "브레네 브라운", category: "자신감과 용기", type: "foreign-author" },
  { text: "용기란 두려움이 전혀 없는 상태가 아니에요.\n오히려 두려움을 느끼면서도 그 앞에 서는 마음,\n바로 그 순간에 진정한 용기가 피어나는 법이죠.", source: "조셉 캠벨", category: "자신감과 용기", type: "foreign-author" },
  { text: "너의 마음 깊은 곳에서 우러나오는 신념을 소중히 간직하며 살아가세요.\n어떤 어려움이 닥쳐도 흔들리지 않고, 그 믿음이 당신을 지켜줄 거예요.", source: "조셉 캠벨", category: "자신감과 용기", type: "foreign-author" },
  { text: "영웅이란 두려움이 없어서가 아니라, 그 두려움을 마주하고도 한 걸음 나아가는 사람입니다.\n두려움이 마음을 짓누를 때마다 용기를 내어 극복하는 그 순간이야말로 진정한 영웅의 시작입니다.", source: "조셉 캠벨", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 언제나 너 자신의 가장 든든한 영웅이에요.\n세상이 아무리 힘들어도,\n스스로를 믿고 지켜주는 존재는 바로 너뿐이니까요.", source: "조셉 캠벨", category: "자신감과 용기", type: "foreign-author" },
  { text: "자신감은 우리 마음속 깊이 숨겨진 빛과 같아요.\n그 빛을 믿고 나아갈 때, 비로소 성공의 문이 활짝 열리게 되지요. 자신감을 품고 한 걸음씩 걸어가다 보면,\n꿈에 한 발짝 더 가까워질 거예요.", source: "조셉 캠벨", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 이미 충분히 강하고 소중한 존재예요.\n조금씩 앞으로 나아가다 보면,\n어떤 어려움도 결국 이겨낼 수 있을 거예요.", source: "노먼 빈센트 필", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 이미 많은 어려움을 이겨내며 살아왔고,\n그 과정에서 자신의 힘을 키워왔다는 것을 잊지 마세요.\n어떤 순간에도 너는 충분히 강하고, 스스로를 믿을 자격이 있어요.", source: "노먼 빈센트 필", category: "자신감과 용기", type: "foreign-author" },
  { text: "우리 안에 있는 약점들은 결코 부끄러운 것이 아니에요.\n오히려 그 약점들이 모여서 우리만의 특별한 강점이 될 수 있답니다.\n그 작은 부분들을 사랑하고 다듬어 나가면, 언젠가 빛나는 힘으로 돌아올 거예요.", source: "노먼 빈센트 필", category: "자신감과 용기", type: "foreign-author" },
  { text: "너만의 목소리를 꼭 내어보세요.  \n세상의 소음 속에서도 당신의 진심이 담긴 작은 목소리는  \n누군가의 마음을 따뜻하게 밝혀줄 거예요.", source: "노먼 빈센트 필", category: "자신감과 용기", type: "foreign-author" },
  { text: "두려움을 한 걸음씩 마주하며 넘어설 때마다\n조금씩 마음속에 자신감이 자라납니다.\n그 과정이 바로 우리를 더 강하게 만드는 힘이 되어주지요.", source: "노먼 빈센트 필", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 그 자체로 이미 소중하고 빛나는 존재예요.\n어떤 상황에서도 변하지 않는 너의 가치를 잊지 말아요.\n세상이 너를 알아봐 주지 않아도, 너는 충분히 가치 있는 사람이에요.", source: "웨인 다이어", category: "자신감과 용기", type: "foreign-author" },
  { text: "너의 가능성은 무한히 펼쳐져 있어요.\n스스로를 믿고 한 걸음씩 나아가다 보면,\n언젠가 그 꿈들이 현실이 될 거예요.", source: "웨인 다이어", category: "자신감과 용기", type: "foreign-author" },
  { text: "과거는 이미 지나간 시간일 뿐이에요.\n그 안에 머무르기보다는,\n지금 이 순간을 살아가며 새로운 길을 만들어가야 해요.", source: "웨인 다이어", category: "자신감과 용기", type: "foreign-author" },
  { text: "미래는 멀리 있는 것이 아니라  \n지금 이 순간, 너의 손끝에 있어요.  \n작은 선택들이 모여서 너만의 길을 만들어가니  \n두려워 말고 용기 있게 나아가 보세요.", source: "웨인 다이어", category: "자신감과 용기", type: "foreign-author" },
  { text: "너 자신을 진심으로 사랑해 주세요.\n내면의 작은 빛 하나하나가 모여서\n당신만의 아름다운 이야기가 되니까요.", source: "웨인 다이어", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 세상에 단 하나뿐인 존재예요.\n그 누구와도 비교할 수 없는 소중한 빛을 가졌으니,\n그 특별함을 항상 기억하며 살아가길 바랄게요.", source: "세스 고딘", category: "자신감과 용기", type: "foreign-author" },
  { text: "진정한 너 자신을 숨기지 말고 마음껏 드러내 보세요.\n그 안에 담긴 빛나는 가치와 아름다움이 세상에 전해질 수 있도록,\n마음 깊은 곳에서 우러나오는 너의 모습을 사랑하며 살아가길 바랍니다.", source: "세스 고딘", category: "자신감과 용기", type: "foreign-author" },
  { text: "거짓 없이 살아가는 것은 마음의 짐을 덜어내는 일이에요.\n스스로에게 솔직할 때 비로소 진정한 평화와 자유를 느낄 수 있답니다.\n매 순간 진실된 모습으로 세상을 마주해 보세요.", source: "세스 고딘", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 너 자신으로 살아가야 해요.\n다른 누구도 아닌, 오직 너만이 가진 빛을 세상에 보여주는 것,\n그것이 진정한 행복의 시작이니까요.", source: "세스 고딘", category: "자신감과 용기", type: "foreign-author" },
  { text: "진정성은 우리 마음 깊은 곳에서 우러나오는 진심이에요.\n그 진심이 모여서 비로소 진정한 성공의 씨앗이 되지요.\n꾸밈없이 자신을 사랑할 때, 그 길 위에 빛나는 결실이 맺힙니다.", source: "세스 고딘", category: "자신감과 용기", type: "foreign-author" },
  { text: "너는 이미 마음속 깊은 곳에 용기의 씨앗을 품고 있어요.\n그것이 자라나 어려움 앞에서도 흔들리지 않게 해주죠.\n그러니 자신을 믿고 한 걸음 한 걸음 나아가 보세요.", source: "수잔 제퍼스", category: "자신감과 용기", type: "foreign-author" },
  { text: "두려움은 결코 약한 마음의 표시가 아니에요.\n오히려 두려움을 마주하는 용기 있는 사람만이 진정 강한 법이죠.\n그 마음 속 깊은 곳에서 피어나는 힘을 믿어보세요.", source: "수잔 제퍼스", category: "자신감과 용기", type: "foreign-author" },
  { text: "두려움은 우리 마음속에 숨어 있지만,\n그것을 마주할 때 비로소 성장할 수 있어요.\n용기를 내서 한 걸음 내딛는 순간,\n너의 세상은 조금 더 넓어질 거예요.", source: "수잔 제퍼스", category: "자신감과 용기", type: "foreign-author" },
  { text: "용기는 마음속에서만 머무는 것이 아니에요.\n진짜 용기는 용감한 한 걸음, 작은 행동에서부터 시작된답니다.\n그 한걸음이 모여 우리를 더 강하게 만들어 주니까요.", source: "수잔 제퍼스", category: "자신감과 용기", type: "foreign-author" },
  
  // 우정과 응원
  { text: "진정한 친구는 언제나 네 곁에 있어요.\n어떤 순간에도 변함없이 함께하며,\n그 존재만으로 큰 힘이 되어주니까요.", source: "마크 트웨인", category: "우정과 응원", type: "foreign-author" },
  { text: "혼자가 아니에요.\n어려울 때마다 곁에 있어 주는 친구가 있으니까요.\n그 따뜻한 손길이 우리를 더욱 강하게 만들어요.", source: "마크 트웨인", category: "우정과 응원", type: "foreign-author" },
  { text: "친구는 단순한 사람이 아니에요.\n서로를 이해하고 아껴주는 마음이 쌓여,\n언제나 곁에 있는 가족과도 같은 존재랍니다.", source: "마크 트웨인", category: "우정과 응원", type: "foreign-author" },
  { text: "함께라면 어떤 어려움도 두렵지 않아요.\n서로의 손을 잡고 걸어가면,\n모든 것이 가능해진답니다.", source: "마크 트웨인", category: "우정과 응원", type: "foreign-author" },
  { text: "너를 믿어주는 친구 한 사람만 있어도  \n그것만으로도 삶은 든든하고 의미가 깊어져요.  \n서로의 마음을 지켜주는 그런 친구가 곁에 있다는 것,  \n그 자체로 이미 큰 축복이랍니다.", source: "마크 트웨인", category: "우정과 응원", type: "foreign-author" },
  { text: "친구는 너의 거울과 같아서\n네가 어떤 사람인지 비춰주는 존재예요.\n서로를 통해 자신을 더 깊이 이해하게 되지요.", source: "랄프 왈도 에머슨", category: "우정과 응원", type: "foreign-author" },
  { text: "진정한 친구란 시간이 흘러도 변하지 않는 소중한 인연이에요.\n서로의 마음을 이해하고 지켜주기에, 그 우정은 영원히 빛나죠.", source: "랄프 왈도 에머슨", category: "우정과 응원", type: "foreign-author" },
  { text: "친구와 함께 나눈 소중한 추억들은 시간이 지나도 변하지 않는 보물이 되어 남아요.\n그 순간들은 우리 마음 깊은 곳에 따뜻한 빛으로 스며들어,\n언제나 힘이 되고 위로가 되어준답니다.", source: "랄프 왈도 에머슨", category: "우정과 응원", type: "foreign-author" },
  { text: "친구는 인생에서 가장 소중한 보물이기에\n결코 그들을 잃지 않도록 마음을 다해 아껴야 합니다.\n서로의 곁에 있어주는 따뜻한 존재가 되어주세요.", source: "랄프 왈도 에머슨", category: "우정과 응원", type: "foreign-author" },
  { text: "친구는 우리 삶에 깊은 영향을 주는 소중한 존재예요.\n그들과 함께하는 순간들이 쌓여서\n우리 인생의 방향과 빛을 바꾸어 놓지요.", source: "랄프 왈도 에머슨", category: "우정과 응원", type: "foreign-author" },
  { text: "함께 웃을 때 그 기쁨은 배가 되고,\n함께 울 때 그 슬픔도 나누면 가벼워져요.\n서로의 마음을 나누며 진정한 인연을 만들어가세요.", source: "조지 엘리엇", category: "우정과 응원", type: "foreign-author" },
  { text: "사랑하는 사람들과 함께하는 시간은 우리 마음에 가장 깊은 위로를 줍니다.\n서로의 온기를 느끼며 소중한 순간들을 나누는 것만큼 값진 일은 없어요.\n그러니 언제나 가까운 이들과 함께하며 사랑을 키워가세요.", source: "조지 엘리엇", category: "우정과 응원", type: "foreign-author" },
  { text: "가장 소중한 보물은 멀리 있지 않아요.\n가족과 친구라는 따뜻한 마음들이 우리 곁에 있으니까요.\n그들의 사랑이야말로 인생에서 가장 귀한 선물입니다.", source: "조지 엘리엇", category: "우정과 응원", type: "foreign-author" },
  { text: "함께하는 시간은 그 무엇과도 바꿀 수 없는 소중한 순간이에요.\n서로의 마음이 닿아 따뜻함으로 가득 채워질 때,\n그 시간이 가장 아름답게 빛나는 법이랍니다.", source: "조지 엘리엇", category: "우정과 응원", type: "foreign-author" },
  { text: "너를 응원하는 사람이 분명히 있어요.\n혼자라고 느껴질 때도 그 마음을 기억하며,\n조금씩 힘을 내어 걸어가면 좋겠어요.", source: "조지 엘리엇", category: "우정과 응원", type: "foreign-author" },
  { text: "친구의 응원은 마음 깊은 곳에서부터 힘이 되어 줘요.\n어려운 순간에도 그 따뜻한 말 한마디가\n우리에게 다시 일어설 용기를 선물하죠.", source: "빅토르 위고", category: "우정과 응원", type: "foreign-author" },
  { text: "혼자가 아니라는 것을 꼭 기억하세요.\n어떤 순간에도 당신 곁에는 보이지 않는 손길이 있고,\n함께하는 마음이 항상 함께하고 있으니까요.", source: "빅토르 위고", category: "우정과 응원", type: "foreign-author" },
  { text: "친구는 우리 삶에서 가장 소중한 보물이자\n어떤 어려움도 함께 이겨낼 수 있는 든든한 버팀목이에요.\n진정한 친구가 있다는 것은 무엇과도 바꿀 수 없는 큰 자산이랍니다.", source: "빅토르 위고", category: "우정과 응원", type: "foreign-author" },
  { text: "함께하는 힘은 혼자일 때보다 훨씬 더 크고 따뜻해요.\n서로 손을 맞잡으면 어떤 어려움도 이겨낼 수 있답니다.\n그래서 우리는 혼자가 아니라 함께일 때 진정한 강함을 느끼게 되는 거예요.", source: "빅토르 위고", category: "우정과 응원", type: "foreign-author" },
  { text: "친구가 나를 믿어줄 때, 그 믿음은 내 안에 깊은 힘이 되어 깃든다.\n그 덕분에 나는 어려움 앞에서도 흔들리지 않고 더 단단해질 수 있어요.", source: "빅토르 위고", category: "우정과 응원", type: "foreign-author" },
  { text: "너를 언제나 응원해 주는 사람들이 있어요.\n혼자라고 느껴질 때마다 그들의 마음을 떠올리면\n조금은 더 힘이 날 거예요.", source: "헬렌 켈러", category: "우정과 응원", type: "foreign-author" },
  { text: "함께라면 어떤 어려움도 이겨낼 수 있어요.\n서로의 손을 잡고 마음을 나누면,\n두려움은 저 멀리 사라져 버리니까요.", source: "헬렌 켈러", category: "우정과 응원", type: "foreign-author" },
  { text: "친구는 언제나 네 곁에서\n가장 큰 힘이 되어주는 존재예요.\n서로의 마음을 든든하게 지켜주기에,\n삶의 무게도 함께 나눌 수 있답니다.", source: "헬렌 켈러", category: "우정과 응원", type: "foreign-author" },
  { text: "함께 나누는 기쁨이야말로\n우리 삶에서 가장 소중하고 큰 행복이에요.\n서로의 마음을 나누며 느끼는 그 순간이야말로 진정한 기쁨이죠.", source: "헬렌 켈러", category: "우정과 응원", type: "foreign-author" },
  { text: "친구의 응원 없이는 진정한 성공을 이루기 어렵습니다.\n함께 기뻐해주고 힘이 되어주는 이들이 있기에,\n우리는 더 멀리 나아갈 수 있습니다.", source: "헬렌 켈러", category: "우정과 응원", type: "foreign-author" },

  // ========== 국내 영화·드라마 명대사 (200개) ==========
  
  // 공부와 노력
  { text: "공부는 결코 우리를 외면하지 않아요.\n꾸준히 쌓아온 작은 노력이 모여서,\n언젠가 반드시 빛나는 결실로 돌아오니까요.", source: "드라마 SKY 캐슬 (2018)", category: "공부와 노력", type: "korean-movie" },
  { text: "최선을 다하는 것만큼 소중한 일은 없어요.\n결과에 너무 연연하지 말고,\n그저 자신의 마음에 부끄럽지 않도록 노력해 보세요.", source: "드라마 SKY 캐슬 (2018)", category: "공부와 노력", type: "korean-movie" },
  { text: "노력은 결코 우리를 배신하지 않아요.\n꾸준히 쌓아 올린 작은 땀방울들이 결국에는 큰 결실로 돌아오니까요.\n포기하지 않고 계속 나아가는 그 마음이 가장 소중한 진실입니다.", source: "드라마 SKY 캐슬 (2018)", category: "공부와 노력", type: "korean-movie" },
  { text: "우리는 어떤 상황에서도 멈추지 않고,\n조금씩 천천히라도 앞으로 나아가야 해요.\n그 작은 발걸음들이 결국 우리를 더 나은 곳으로 이끌 테니까요.", source: "드라마 SKY 캐슬 (2018)", category: "공부와 노력", type: "korean-movie" },
  { text: "너는 지금 이 순간에도 충분히 잘하고 있어요.\n때로는 힘들고 지칠 때도 있겠지만,\n그 모든 과정이 너의 성장이고 빛나는 발걸음이니까요.", source: "드라마 SKY 캐슬 (2018)", category: "공부와 노력", type: "korean-movie" },
  { text: "공부가 인생의 전부는 아니에요.\n하지만 그 안에서 쌓이는 작은 노력들이\n우리의 미래를 밝히는 중요한 빛이 되어준답니다.", source: "드라마 응답하라 1988 (2015)", category: "공부와 노력", type: "korean-movie" },
  { text: "지금 이 순간은 다시 오지 않는 소중한 시간이에요.\n작은 행복과 감동을 놓치지 말고 마음 깊이 간직하세요.\n그래서 매일이 특별한 의미로 가득 차게 될 거예요.", source: "드라마 응답하라 1988 (2015)", category: "공부와 노력", type: "korean-movie" },
  { text: "노력하는 그 순간이야말로 진정한 아름다움이 피어나는 때입니다.\n힘들고 지칠지라도 포기하지 않고 한 걸음씩 나아가는 모습이 우리 마음을 따뜻하게 만듭니다.", source: "드라마 응답하라 1988 (2015)", category: "공부와 노력", type: "korean-movie" },
  { text: "계속 나아가는 것이 가장 소중한 일입니다.\n비록 천천히 걸어가더라도 포기하지 않고 한 걸음씩 앞으로 나아갈 때,\n그 길 끝에 우리가 바라는 모습이 기다리고 있을 거예요.", source: "드라마 응답하라 1988 (2015)", category: "공부와 노력", type: "korean-movie" },
  { text: "너는 이미 그 자체로 충분히 소중하고 아름다워요.\n남들의 기준에 흔들리지 말고,\n스스로를 따뜻하게 안아주세요.", source: "드라마 응답하라 1988 (2015)", category: "공부와 노력", type: "korean-movie" },
  { text: "공부는 단순한 시간이 아니라,\n내가 앞으로 걸어갈 길을 차곡차곡 쌓아가는 과정이에요.\n오늘의 작은 노력이 결국 나의 밝은 미래를 만들어준답니다.", source: "영화 200 폰드 뷰티 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "노력하는 마음이 있다면\n불가능해 보이는 일도 조금씩 가까워질 거예요.  \n포기하지 않고 한 걸음씩 나아간다면,\n언젠가는 원하는 꿈에 닿을 수 있답니다.", source: "영화 200 폰드 뷰티 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "성공이란 멀리 있는 어떤 목표가 아니라,  \n포기하지 않고 한 걸음 한 걸음씩  \n꾸준히 나아가는 그 과정 자체에 있어요.  \n멈추지 않고 걸어가는 당신의 발걸음이  \n바로 진정한 성공의 의미랍니다.", source: "영화 200 폰드 뷰티 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "너는 이미 마음속 깊이 강인함을 품고 있어요.\n어떤 어려움이 와도 흔들리지 않고,\n스스로를 믿으며 나아갈 수 있는 힘이 충분히 있다는 것을 잊지 마세요.", source: "영화 200 폰드 뷰티 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "최선을 다하는 그 순간이 바로 당신이 가장 빛나는 순간이에요.\n비교하지 말고, 오직 지금의 나에게 집중하며\n한 걸음 한 걸음 진심을 담아 나아가면 됩니다.", source: "영화 200 폰드 뷰티 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "공부는 나에게 새로운 세상의 문을 열어 주고,\n나를 더 넓은 곳으로 이끌어 주는 열쇠와 같아요.\n그렇게 나는 스스로의 한계를 넘어 자유로워질 수 있답니다.", source: "드라마 펜트하우스 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "성공은 결코 저절로 찾아오지 않아요.\n꾸준한 노력과 인내가 쌓여서 비로소 이루어지는 거죠.\n그래서 매 순간 최선을 다하는 당신이 더욱 빛나는 거예요.", source: "드라마 펜트하우스 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "우리가 가는 길이 때로는 멀고 험난해 보여도\n멈추지 않고 꾸준히 나아가는 것만이 진정한 힘이 됩니다.\n조금씩 앞으로 나아가는 그 발걸음이 결국 큰 변화를 만들어내니까요.", source: "드라마 펜트하우스 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "너는 지금 이 순간에도 충분히 잘하고 있어요.\n조금씩 성장해가고 있다는 사실을 잊지 마세요.\n스스로를 믿고 천천히 나아가도 괜찮답니다.", source: "드라마 펜트하우스 (2020)", category: "공부와 노력", type: "korean-movie" },
  { text: "우리가 할 수 있는 최선의 노력을 다하는 것만으로도 충분해요.\n결과가 어떻든 간에, 그 과정에서 진심을 다했다면 마음이 편안해질 거예요.  \n스스로에게 부끄럽지 않도록, 오늘도 최선을 다해보세요.", source: "드라마 펜트하우스 (2020)", category: "공부와 노력", type: "korean-movie" },
  
  // 극복과 도전
  { text: "불가능이라는 것은 사실 우리 마음속에만 존재하는 거예요.\n조금 더 용기를 내고, 한 걸음 더 나아가면\n그 어떤 어려움도 결국에는 이겨낼 수 있답니다.", source: "영화 국가대표 (2009)", category: "극복과 도전", type: "korean-movie" },
  { text: "우리는 마음속에 늘 작은 불씨를 품고 있어요.\n그 불씨가 큰 불꽃이 되어 어려움도 이겨낼 수 있다는 믿음을 줍니다.\n그래서 우리는 언제나 할 수 있다는 힘을 잃지 않고 나아갈 수 있어요.", source: "영화 국가대표 (2009)", category: "극복과 도전", type: "korean-movie" },
  { text: "절대 포기하지 말아요.\n어떤 어려움이 와도 마음을 굳게 먹고 견뎌내면,\n반드시 빛나는 내일이 찾아올 거예요.", source: "영화 국가대표 (2009)", category: "극복과 도전", type: "korean-movie" },
  { text: "함께라면 어떤 어려움도 이겨낼 수 있어요.\n서로의 손을 잡고 나아갈 때, 불가능해 보였던 일들도\n조금씩 현실이 되어 가는 마법 같은 순간이 찾아옵니다.", source: "영화 국가대표 (2009)", category: "극복과 도전", type: "korean-movie" },
  { text: "우리는 생각보다 훨씬 더 강한 존재예요.\n어려움이 닥쳐도 넘어지지 않고,\n다시 일어설 힘이 우리 안에 늘 숨 쉬고 있답니다.", source: "영화 국가대표 (2009)", category: "극복과 도전", type: "korean-movie" },
  { text: "고통은 잠시 머무르는 손님과 같아서,\n언젠가는 반드시 떠나가고 맑은 날이 찾아옵니다.\n그러니 지금의 어려움도 지나갈 것임을 믿으며 견뎌내세요.", source: "영화 택시운전사 (2017)", category: "극복과 도전", type: "korean-movie" },
  { text: "진실은 언제나 빛을 발하며 결국 모든 어둠을 이겨냅니다.\n비록 그 길이 험하고 멀어 보여도,\n마지막에는 진실이 우리 마음을 따뜻하게 감싸줄 거예요.", source: "영화 택시운전사 (2017)", category: "극복과 도전", type: "korean-movie" },
  { text: "올바른 길을 걷는다는 것은\n때로는 쉽지 않은 선택일 수 있어요.\n하지만 그 길 위에서 우리는 진정한 자신을 만나고,\n마음의 평화를 찾을 수 있답니다.", source: "영화 택시운전사 (2017)", category: "극복과 도전", type: "korean-movie" },
  { text: "용기를 내어 한 걸음 내딛어 보세요.\n그 작은 용기가 당신의 세상을 조금씩 바꾸어 갈 테니까요.\n두려움 속에서도 빛나는 당신의 마음을 믿으세요.", source: "영화 택시운전사 (2017)", category: "극복과 도전", type: "korean-movie" },
  { text: "너는 이미 마음속 깊은 곳에서부터 용기를 품고 있어요.\n때로는 자신을 믿기 어려울 때도 있지만,\n그 용기가 너를 앞으로 나아가게 할 거예요.", source: "영화 택시운전사 (2017)", category: "극복과 도전", type: "korean-movie" },
  { text: "위기는 우리에게 찾아오는 뜻밖의 손님과 같아요.\n처음에는 두렵고 불안할 수 있지만,\n그 안에는 새로운 기회와 성장의 씨앗이 숨겨져 있답니다.", source: "영화 암살 (2015)", category: "극복과 도전", type: "korean-movie" },
  { text: "절대 포기하지 말아요.\n어떤 어려움이 닥쳐도 마음속 깊이 희망을 품고,\n끝까지 나아가는 그 힘이 당신을 빛나게 할 거예요.", source: "영화 암살 (2015)", category: "극복과 도전", type: "korean-movie" },
  { text: "우리는 누구나 마음속에 작은 힘을 품고 있어요.\n어려움이 찾아와도 포기하지 않고,\n스스로를 믿으면 결국 해낼 수 있답니다.", source: "영화 암살 (2015)", category: "극복과 도전", type: "korean-movie" },
  { text: "함께라면 우리는 어떤 어려움도 이겨낼 수 있어요.\n서로의 손을 잡고 마음을 나누면,\n그 어떤 시련도 두렵지 않은 강한 힘이 생기니까요.", source: "영화 암살 (2015)", category: "극복과 도전", type: "korean-movie" },
  { text: "너는 이미 마음속 깊은 곳에\n누구도 꺾을 수 없는 강인함을 품고 있어요.\n때로 힘들어도, 그 힘으로 충분히 이겨낼 수 있다는 걸 잊지 마세요.", source: "영화 암살 (2015)", category: "극복과 도전", type: "korean-movie" },
  { text: "고통은 우리를 괴롭히지만,\n그 안에서 우리는 조금씩 단단해져요.\n아픔을 견디며 성장하는 마음이야말로 진정한 강함이랍니다.", source: "드라마 미생 (2014)", category: "극복과 도전", type: "korean-movie" },
  { text: "성공이란 멀리 있는 목표만을 바라보는 것이 아니에요.\n작은 걸음이라도 멈추지 않고 꾸준히 앞으로 나아가는 그 자체가 바로 성공인 거죠.\n포기하지 않고 계속 걸어가는 당신의 모습이 진정한 승리입니다.", source: "드라마 미생 (2014)", category: "극복과 도전", type: "korean-movie" },
  { text: "절대 포기하지 말아요.\n어떤 어려움이 찾아와도,\n그 끝에는 분명히 빛나는 희망이 기다리고 있으니까요.", source: "드라마 미생 (2014)", category: "극복과 도전", type: "korean-movie" },
  { text: "너는 지금 이 순간에도 충분히 잘하고 있어요.\n때로는 자신을 의심할 때도 있겠지만,\n그 모든 노력이 결국 너를 빛나게 만들 거예요.", source: "드라마 미생 (2014)", category: "극복과 도전", type: "korean-movie" },
  { text: "최선을 다하는 것만으로도 충분해요.\n결과가 어떻든 상관없이,\n그 과정 속에서 우리는 성장하고 빛나니까요.", source: "드라마 미생 (2014)", category: "극복과 도전", type: "korean-movie" },
  
  // 꿈과 목표
  { text: "꿈을 마음에 품고 조용히 시작해 보세요.\n그 작은 한 걸음이 결국 당신의 세상을 바꿀 거예요.\n꿈은 행동으로만 현실이 된답니다.", source: "영화 건축학 개론 (2012)", category: "꿈과 목표", type: "korean-movie" },
  { text: "너의 꿈은 단순한 바람이 아니에요.\n그것은 바로 너를 이루는 가장 소중한 조각이며,\n네가 누구인지 말해주는 진짜 이야기랍니다.", source: "영화 건축학 개론 (2012)", category: "꿈과 목표", type: "korean-movie" },
  { text: "목표를 향해 한 걸음씩 천천히 나아가세요.\n비록 길이 멀고 어려워 보여도,\n그 꾸준한 발걸음이 결국 당신을 빛나는 곳으로 데려다줄 거예요.", source: "영화 건축학 개론 (2012)", category: "꿈과 목표", type: "korean-movie" },
  { text: "너의 마음속 깊이 간직한 꿈을 절대로 포기하지 마세요.\n어떤 어려움이 닥쳐도 그 빛나는 희망을 붙잡고\n조금씩 한 걸음씩 나아가는 것이 진정한 용기입니다.", source: "영화 건축학 개론 (2012)", category: "꿈과 목표", type: "korean-movie" },
  { text: "꿈은 단순한 바람에 그치지 않아요.\n꾸준한 노력과 믿음이 더해질 때,\n비로소 현실 속에서 빛을 발하게 된답니다.", source: "영화 건축학 개론 (2012)", category: "꿈과 목표", type: "korean-movie" },
  { text: "목표는 분명해야 해요.\n그래야만 흔들리지 않고 한 걸음씩 나아갈 수 있거든요.\n마음속에 뚜렷한 방향이 있다면, 어떤 어려움도 이겨낼 힘이 생겨요.", source: "드라마 도깨비 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "목표를 향해 한 걸음씩 나아가세요.\n비록 길이 멀고 험해도,\n그 한 걸음 한 걸음이 결국 당신을 꿈에 가까이 데려다줄 거예요.", source: "드라마 도깨비 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "너의 마음속에 품은 비전을 소중히 간직하며,\n그 꿈을 현실로 만들어 가는 여정을 멈추지 마세요.\n작은 한 걸음 한 걸음이 결국 당신의 미래를 밝히는 빛이 될 거예요.", source: "드라마 도깨비 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "꿈을 이루는 길은 결코 쉽지 않아요.\n때로는 넘어지고 좌절할 때도 있겠지만,\n그래도 그 꿈은 충분히 이루어질 수 있는 가능성으로 가득하답니다.", source: "드라마 도깨비 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "목표가 없으면 마치 나침반 없이 바다를 항해하는 것과 같아요.\n어디로 가야 할지 몰라서 헤매기 쉽지만,\n작은 목표 하나가 당신의 길을 밝혀 줄 거예요.", source: "드라마 도깨비 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "꿈을 이루기 위해서는 때로 소중한 것들을 내려놓아야 해요.\n희생이라는 작은 불편함이 모여,\n우리의 꿈을 더욱 빛나게 만들어 주니까요.", source: "영화 명량 (2014)", category: "꿈과 목표", type: "korean-movie" },
  { text: "목표를 향한 집중력은 우리를 성장시키는 힘이에요.\n작은 순간에도 흔들리지 않고 마음을 모을 때, 비로소 진정한 성공이 찾아옵니다.  \n꾸준한 집중이 쌓여 꿈을 현실로 만들어 가는 과정이니까요.", source: "영화 명량 (2014)", category: "꿈과 목표", type: "korean-movie" },
  { text: "꿈은 크면 클수록 더 아름답고 값진 법이에요.\n그 큰 꿈이 우리를 더욱 멀리 나아가게 하고,\n삶에 깊은 의미와 희망을 선물해 주니까요.", source: "영화 명량 (2014)", category: "꿈과 목표", type: "korean-movie" },
  { text: "너의 꿈은 그저 바람처럼 머무는 것이 아니라,\n항상 너의 길을 밝혀주는 빛이 되어야 해요.\n그 꿈이 너를 부드럽게 이끌며,\n어둠 속에서도 멈추지 않고 나아가게 해줄 거예요.", source: "영화 명량 (2014)", category: "꿈과 목표", type: "korean-movie" },
  { text: "목표를 향해 한 걸음씩 나아가세요.\n작은 발걸음도 모이면 큰 길이 되고,\n그 길 위에서 당신의 꿈은 조금씩 현실이 될 거예요.", source: "영화 명량 (2014)", category: "꿈과 목표", type: "korean-movie" },
  { text: "꿈을 크게 꾸고 그 꿈을 향해 한 걸음씩 나아가세요.\n생각만으로는 부족하니, 용기 내어 행동할 때 비로소 꿈은 현실이 됩니다.", source: "드라마 시그널 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "목표가 없다면, 성공이라는 열매를 거둘 수 없어요.\n작은 꿈 하나가 우리를 앞으로 나아가게 하는 등불이 되니까요.\n그 빛을 따라 한 걸음씩 나아가다 보면, 어느새 원하는 곳에 닿을 수 있을 거예요.", source: "드라마 시그널 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "너의 목표를 분명하게 세워봐요.\n그렇게 하면 흔들릴 때마다 다시 중심을 잡을 수 있으니까요.\n명확한 목표가 우리를 한 걸음씩 앞으로 나아가게 해줍니다.", source: "드라마 시그널 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "목표를 향해 한 걸음 한 걸음 천천히 나아가세요.\n비록 길이 멀고 험해도 포기하지 않는 마음이\n결국 당신을 원하는 곳으로 인도할 거예요.", source: "드라마 시그널 (2016)", category: "꿈과 목표", type: "korean-movie" },
  { text: "꿈은 결코 멀리 있는 이야기가 아니에요.\n꾸준한 노력과 믿음이 모여서 마침내 현실이 될 수 있답니다.\n포기하지 않고 한 걸음씩 나아가 보세요.", source: "드라마 시그널 (2016)", category: "꿈과 목표", type: "korean-movie" },
  
  // 자신감과 용기
  { text: "너는 이미 그 자체로 충분히 아름답고 소중한 사람이에요.\n다른 누구와도 비교할 필요 없이,\n지금 이 순간의 너를 사랑해도 괜찮아요.", source: "영화 아이 캔 스피크 (2017)", category: "자신감과 용기", type: "korean-movie" },
  { text: "자신을 믿는 마음이야말로 가장 든든한 힘이 되어줍니다.\n어떤 어려움이 찾아와도 흔들리지 말고,\n용기 있게 한 걸음씩 앞으로 나아가 보세요.", source: "영화 아이 캔 스피크 (2017)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너는 세상에 단 하나뿐인 소중한 존재예요.\n스스로의 가치를 잊지 말고,\n자신을 사랑하는 마음을 늘 간직하세요.", source: "영화 아이 캔 스피크 (2017)", category: "자신감과 용기", type: "korean-movie" },
  { text: "두려움은 결코 약함의 표시가 아니에요.\n오히려 두려움을 마주하는 용기와 강인함이 담겨 있답니다.\n그 마음 속 깊은 곳에서부터 성장해 나가는 힘을 믿어보세요.", source: "영화 아이 캔 스피크 (2017)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너는 이미 그 자체로 충분히 훌륭한 사람이에요.\n남과 비교하지 않아도 되고,\n있는 모습 그대로 빛나고 있음을 잊지 마세요.", source: "영화 아이 캔 스피크 (2017)", category: "자신감과 용기", type: "korean-movie" },
  { text: "용기란 두려움이 완전히 사라지는 것이 아니에요.\n오히려 두려움을 마주하고도 한 걸음 내딛는 그 힘을 말하는 거죠.\n그래서 진정한 용기는 우리 안에 숨겨진 소중한 빛과도 같답니다.", source: "영화 서울의 봄 (2023)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너의 마음 깊은 곳에서 우러나오는 신념을 꼭 지켜 나가세요.\n세상이 흔들려도, 그 믿음이 당신을 든든히 지켜줄 거예요.", source: "영화 서울의 봄 (2023)", category: "자신감과 용기", type: "korean-movie" },
  { text: "영웅이란 두려움이 없는 사람이 아니에요.\n진짜 영웅은 두려움 앞에서 주저하지 않고,\n그 두려움을 용기로 바꾸는 사람입니다.", source: "영화 서울의 봄 (2023)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너는 언제나 너 자신의 가장 큰 영웅이에요.\n어떤 어려움이 와도 스스로를 믿고 이겨내는 힘이 바로 너에게 있답니다.\n그 힘으로 오늘도 한 걸음씩 빛나는 길을 걸어가세요.", source: "영화 서울의 봄 (2023)", category: "자신감과 용기", type: "korean-movie" },
  { text: "자신감은 우리 마음속에 숨겨진 소중한 열쇠와 같아요.\n그 열쇠를 잘 쥐고 있을 때 비로소 성공의 문이 활짝 열리죠.\n그러니 스스로를 믿고 한 걸음씩 나아가는 용기를 잃지 마세요.", source: "영화 서울의 봄 (2023)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너는 이미 마음속 깊은 곳에 그 힘을 품고 있어요.\n조금만 믿고 용기를 내면, 무엇이든 해낼 수 있을 거예요.  \n포기하지 말고 천천히 걸어가다 보면,\n반드시 원하는 곳에 도착할 수 있을 거예요.", source: "드라마 이상한 변호사 우영우 (2022)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너는 이미 많은 어려움을 견뎌냈고,\n그 과정에서 더 단단해졌다는 것을 잊지 마세요.\n당신 안에는 세상을 이겨낼 수 있는 충분한 힘이 있어요.", source: "드라마 이상한 변호사 우영우 (2022)", category: "자신감과 용기", type: "korean-movie" },
  { text: "약점은 결코 부끄러운 것이 아니에요.\n오히려 그 안에 숨겨진 가능성을 발견하고,\n그 약점을 당신만의 강점으로 바꾸는 용기를 가지세요.", source: "드라마 이상한 변호사 우영우 (2022)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너의 목소리를 꼭 내어야 해요.\n그 작은 소리 하나가 세상을 바꾸는 힘이 될 수 있으니까요.\n조금 두려워도 괜찮으니, 용기를 내어 마음을 전해보세요.", source: "드라마 이상한 변호사 우영우 (2022)", category: "자신감과 용기", type: "korean-movie" },
  { text: "두려움을 마주하고 한 걸음 내디딜 때마다\n조금씩 마음속에 자신감이 자라납니다.\n그 용기가 쌓여 당신을 더욱 빛나게 해줄 거예요.", source: "드라마 이상한 변호사 우영우 (2022)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너는 그 자체로 이미 충분히 가치 있는 사람이에요.\n누구도 너의 존재를 의심할 필요 없고,\n스스로를 사랑하는 마음을 잊지 말아요.", source: "영화 82년생 김지영 (2020)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너 자신 안에 숨겨진 가능성을 믿어봐요.\n아직 발견하지 못한 힘들이 당신을 기다리고 있으니까요.\n그 믿음이 당신을 더 멀리, 더 높이 이끌어 줄 거예요.", source: "영화 82년생 김지영 (2020)", category: "자신감과 용기", type: "korean-movie" },
  { text: "과거는 이미 지나간 시간일 뿐이에요.\n그 안에 머무르기보다는,\n오늘이라는 순간에 마음을 열어보세요.", source: "영화 82년생 김지영 (2020)", category: "자신감과 용기", type: "korean-movie" },
  { text: "미래는 아직 정해지지 않은 빈 캔버스와 같아요.\n그 캔버스 위에 어떤 그림을 그릴지는 오직 너의 손에 달려 있답니다.\n그러니 두려워 말고, 너만의 아름다운 이야기를 마음껏 펼쳐 나가길 바래요.", source: "영화 82년생 김지영 (2020)", category: "자신감과 용기", type: "korean-movie" },
  { text: "너 자신을 진심으로 사랑하는 법을 배워보세요.  \n자신의 부족함도, 강점도 모두 따뜻한 마음으로 안아주며  \n그 안에서 진정한 행복이 피어날 거예요.", source: "영화 82년생 김지영 (2020)", category: "자신감과 용기", type: "korean-movie" },
  
  // 우정과 응원
  { text: "친구는 우리 삶에서 함께 웃고 울며  \n서로의 마음을 나누는 소중한 가족과 같아요.  \n진정한 친구는 혈연을 넘어선 따뜻한 인연이니까요.", source: "드라마 응답하라 1988 (2015)", category: "우정과 응원", type: "korean-movie" },
  { text: "함께라면 어떤 어려움도 이겨낼 수 있어요.\n서로의 손을 잡고 나아간다면,\n모든 일이 꿈처럼 이루어질 거예요.", source: "드라마 응답하라 1988 (2015)", category: "우정과 응원", type: "korean-movie" },
  { text: "너를 진심으로 믿어주는 친구 한 사람이 있다는 것만으로도  \n삶은 훨씬 더 따뜻하고 든든해져요.  \n그 믿음이 힘들 때마다 너를 일으켜 세우는 큰 힘이 되어줄 거예요.", source: "드라마 응답하라 1988 (2015)", category: "우정과 응원", type: "korean-movie" },
  { text: "친구와 함께한 소중한 추억들은 시간이 지나도 마음 깊이 남아\n가장 따뜻한 위로가 되어줍니다.  \n그 무엇보다 소중한 것은 바로 그 순간들이기에  \n우리의 삶을 더욱 빛나게 만드는 보석과도 같습니다.", source: "드라마 응답하라 1988 (2015)", category: "우정과 응원", type: "korean-movie" },
  { text: "친구는 우리의 삶에 깊은 영향을 미쳐요.\n때로는 작은 말 한마디로도 마음을 움직이고,\n함께하는 시간들이 인생의 방향을 바꾸곤 하니까요.", source: "드라마 응답하라 1988 (2015)", category: "우정과 응원", type: "korean-movie" },
  { text: "함께 웃을 때 그 기쁨은 배가 되고,\n함께 울 때 그 슬픔은 반으로 줄어듭니다.\n서로의 마음을 나누며 진정한 동행이 되어주세요.", source: "영화 건축학 개론 (2012)", category: "우정과 응원", type: "korean-movie" },
  { text: "사랑하는 사람들과 함께하는 시간은 우리 삶에 가장 큰 힘이 되어줍니다.\n서로의 온기를 느끼며 마음을 나누는 그 순간들이야말로 진정한 행복의 시작이니까요.  \n그러니 언제나 가까운 이들과 함께하며\n소중한 인연을 더욱 깊이 간직하세요.", source: "영화 건축학 개론 (2012)", category: "우정과 응원", type: "korean-movie" },
  { text: "가족과 친구는 우리 인생에서 가장 소중한 보물이에요.\n그들이 있기에 우리는 힘들 때도 견디고, 기쁠 때는 더욱 빛날 수 있답니다.\n서로의 마음을 따뜻하게 감싸 안으며 함께하는 시간이야말로 진정한 행복이죠.", source: "영화 건축학 개론 (2012)", category: "우정과 응원", type: "korean-movie" },
  { text: "함께하는 시간만큼 소중한 순간은 없어요.\n서로의 온기를 느끼며 나누는 그 시간이야말로\n우리 마음속에 가장 빛나는 아름다움으로 남는답니다.", source: "영화 건축학 개론 (2012)", category: "우정과 응원", type: "korean-movie" },
  { text: "너의 곁에는 언제나 너를 믿고 응원하는 사람이 있어요.\n혼자라고 느껴질 때도 그 마음을 기억하며\n조금 더 힘내볼 수 있길 바랄게요.", source: "영화 건축학 개론 (2012)", category: "우정과 응원", type: "korean-movie" },
  { text: "친구의 따뜻한 응원은 마음 깊은 곳에서부터 힘이 되어줍니다.\n어려운 순간에도 그 한마디가 큰 용기와 희망으로 다가오지요.\n그래서 우리는 서로의 응원을 통해 더 단단해질 수 있습니다.", source: "드라마 미생 (2014)", category: "우정과 응원", type: "korean-movie" },
  { text: "혼자가 아니라는 것을 기억하세요.\n어떤 어려움이 와도,\n당신 곁에는 늘 함께하는 사람들이 있다는 것을요.", source: "드라마 미생 (2014)", category: "우정과 응원", type: "korean-movie" },
  { text: "친구는 우리 삶에서 가장 소중한 보물이자\n언제나 든든한 힘이 되어주는 가장 큰 자산이에요.\n서로의 마음을 나누며 함께할 때, 진정한 행복이 피어나죠.", source: "드라마 미생 (2014)", category: "우정과 응원", type: "korean-movie" },
  { text: "함께라면 어떤 어려움도 이겨낼 수 있어요.\n서로의 힘이 모여 더 큰 힘이 되니까요.\n그래서 우리는 혼자가 아닌, 함께일 때 진짜 강해집니다.", source: "드라마 미생 (2014)", category: "우정과 응원", type: "korean-movie" },
  { text: "친구가 너를 믿어줄 때, 그 믿음은 너에게 큰 힘이 되어줘요.\n혼자일 때보다 더 용기 있고 당당하게 나아갈 수 있게 만드는 소중한 힘이죠.  \n그래서 진정한 친구의 믿음은 네가 어려움을 이겨내고 성장하는 데 큰 밑거름이 된답니다.", source: "드라마 미생 (2014)", category: "우정과 응원", type: "korean-movie" },
  { text: "언제나 너를 응원하고 지지하는 사람들이 곁에 있어요.\n혼자라고 느껴질 때도 그들의 따뜻한 마음을 기억하며 힘을 내길 바라요.  \n네가 걸어가는 길에 함께하는 이들이 있다는 사실이 큰 위로가 될 거예요.", source: "영화 국가대표 (2009)", category: "우정과 응원", type: "korean-movie" },
  { text: "함께라면 어떤 어려움도 견뎌낼 수 있어요.\n서로의 손을 잡고 걸어가면 두려움은 점점 사라지고,\n그 자리에 따뜻한 용기만 가득할 거예요.", source: "영화 국가대표 (2009)", category: "우정과 응원", type: "korean-movie" },
  { text: "친구는 언제나 너의 곁을 지키며\n가장 큰 힘이 되어주는 소중한 존재예요.\n서로가 있기에 우리는 더 강해질 수 있답니다.", source: "영화 국가대표 (2009)", category: "우정과 응원", type: "korean-movie" },
  { text: "함께 나누는 기쁨은 혼자 느끼는 기쁨보다 훨씬 더 깊고 따뜻해요.\n소중한 순간들을 함께 공유할 때, 우리의 마음도 더 가까워지고 세상도 환해진답니다.", source: "영화 국가대표 (2009)", category: "우정과 응원", type: "korean-movie" },
  { text: "혼자서 이루는 성공은 드물어요.  \n진정한 성공 뒤에는 언제나 친구들의 따뜻한 응원과 격려가 함께하기 때문이죠.  \n서로를 믿고 지지할 때, 우리는 더 큰 꿈을 이룰 수 있답니다.", source: "영화 국가대표 (2009)", category: "우정과 응원", type: "korean-movie" },

  // ========== 국내 유명 저자·명사 명언 (200개) ==========
  
  // 공부와 노력
  { text: "공부는 나의 미래를 만드는 소중한 씨앗과 같아요.\n지금 열심히 가꾸는 만큼,\n내일의 나를 더욱 빛나게 해줄 거예요.", source: "박경철 의사", category: "공부와 노력", type: "korean-author" },
  { text: "노력은 결코 우리를 속이지 않아요.\n꾸준히 쌓인 작은 발걸음들이 결국 큰 변화를 만들어내니까요.\n그래서 포기하지 않고 계속 걸어가는 것이 가장 소중한 진실입니다.", source: "박경철 의사", category: "공부와 노력", type: "korean-author" },
  { text: "우리는 어떤 어려움이 있더라도 멈추지 않고\n꾸준히 앞으로 걸어가야 해요.  \n비록 길이 험하고 힘들지라도, 그 한 걸음 한 걸음이\n우리의 삶을 더욱 빛나게 만들어 줄 거예요.", source: "박경철 의사", category: "공부와 노력", type: "korean-author" },
  { text: "너는 지금 이 순간에도 최선을 다하고 있어요.\n때로는 힘들고 지쳐도, 그 자체로 이미 충분히 잘하고 있다는 걸 잊지 마세요.  \n그 마음을 따뜻하게 안아주며 천천히 걸어가면 돼요.", source: "박경철 의사", category: "공부와 노력", type: "korean-author" },
  { text: "우리가 할 수 있는 가장 중요한 일은\n항상 최선을 다하는 거예요.  \n결과가 어떻든 상관없이,\n내가 진심을 다했다는 것만으로도 충분하답니다.", source: "박경철 의사", category: "공부와 노력", type: "korean-author" },
  { text: "공부가 인생의 전부는 아니에요.\n하지만 우리가 앞으로 나아가기 위해서는 꼭 필요한 밑거름이 되어줍니다.\n그래서 조금 힘들어도 소중하게 여기며 꾸준히 해나가야 해요.", source: "유시민 작가", category: "공부와 노력", type: "korean-author" },
  { text: "지금 이 순간은 다시 돌아오지 않는 소중한 시간이기에\n마음 깊이 간직하며 살아가야 해요.  \n바쁘고 힘들더라도 잠시 멈춰서서\n지금 여기에 집중하는 그 순간을 귀하게 여겨보세요.", source: "유시민 작가", category: "공부와 노력", type: "korean-author" },
  { text: "노력하는 그 순간이야말로 진정한 아름다움이 피어나는 때입니다.\n힘들고 지칠지라도 한 걸음 한 걸음 나아가는 모습이 우리를 빛나게 만듭니다.", source: "유시민 작가", category: "공부와 노력", type: "korean-author" },
  { text: "중요한 것은 멈추지 않고 한 걸음씩 앞으로 나아가는 거예요.\n비록 천천히 걸어도 괜찮아요,\n그렇게 계속 나아가는 그 자체가 우리를 성장하게 하니까요.", source: "유시민 작가", category: "공부와 노력", type: "korean-author" },
  { text: "너는 이미 충분히 좋은 사람이에요.\n스스로를 의심하지 말고,\n그 모습 그대로 빛나길 바랄게요.", source: "유시민 작가", category: "공부와 노력", type: "korean-author" },
  { text: "공부는 나 자신을 한층 더 깊이 이해하게 해주고,\n마음의 문을 활짝 열어 진정한 자유를 선물해 줍니다.\n그렇게 배움은 나를 자유롭게 만드는 소중한 열쇠가 되어줍니다.", source: "이어령 교수", category: "공부와 노력", type: "korean-author" },
  { text: "성공은 결코 우연히 찾아오지 않아요.\n꾸준한 노력과 작은 한 걸음들이 모여서야 비로소 이루어지는 것이죠.\n그래서 포기하지 않고 계속 나아가는 마음이 가장 소중해요.", source: "이어령 교수", category: "공부와 노력", type: "korean-author" },
  { text: "때로는 멈추고 싶은 순간도 찾아오지만,\n그럴수록 우리는 조금씩 천천히라도 계속 나아가야 해요.\n포기하지 않고 앞으로 나아갈 때 비로소 새로운 길이 열리니까요.", source: "이어령 교수", category: "공부와 노력", type: "korean-author" },
  { text: "너는 지금 이 순간에도 충분히 잘하고 있어요.\n모든 작은 노력들이 모여서 결국 큰 변화를 만들어내니까,\n자신을 믿고 천천히 걸어가도 괜찮답니다.", source: "이어령 교수", category: "공부와 노력", type: "korean-author" },
  { text: "최선을 다하는 것만으로도 이미 충분해요.\n결과에 연연하지 말고, 지금 이 순간에 집중하며\n당신의 마음을 온전히 담아보세요.", source: "이어령 교수", category: "공부와 노력", type: "korean-author" },
  { text: "공부는 언제나 우리 곁에서 든든한 친구가 되어줍니다.\n힘들고 지칠 때에도 결코 우리를 배신하지 않고,\n꾸준히 노력한 만큼의 결실을 꼭 안겨주니까요.", source: "조용필 가수", category: "공부와 노력", type: "korean-author" },
  { text: "노력하는 마음이 있다면, 불가능해 보이는 일도 조금씩 가까워질 거예요.\n포기하지 않고 한 걸음 한 걸음 나아가면,\n결국에는 원하는 꿈에 닿을 수 있답니다.", source: "조용필 가수", category: "공부와 노력", type: "korean-author" },
  { text: "성공이란 멀리 있는 목표만을 뜻하지 않아요.\n작은 발걸음 하나하나를 멈추지 않고 이어가는 것,\n그 꾸준한 움직임 속에서 진정한 성공이 피어나는 법이랍니다.", source: "조용필 가수", category: "공부와 노력", type: "korean-author" },
  { text: "너는 이미 많은 어려움을 이겨내며 여기까지 왔어요.\n그만큼 너는 충분히 강하고,\n앞으로도 어떤 시련이 와도 이겨낼 수 있을 거예요.", source: "조용필 가수", category: "공부와 노력", type: "korean-author" },
  { text: "최선을 다하는 것만큼 소중한 일은 없어요.\n완벽하지 않아도 괜찮으니,\n그저 자신의 마음을 다해 노력하는 순간이 진정한 최고입니다.", source: "조용필 가수", category: "공부와 노력", type: "korean-author" },
  
  // 극복과 도전
  { text: "불가능이라는 것은 사실 우리 마음속에만 존재하는 말이에요.  \n진심을 다하고 노력한다면, 어떤 어려움도 결국에는 이겨낼 수 있답니다.  \n그러니 포기하지 말고 한 걸음씩 나아가 보세요, 불가능은 결코 없으니까요.", source: "박찬호 야구 선수", category: "극복과 도전", type: "korean-author" },
  { text: "우리는 할 수 있어요.\n때로는 어려워도 포기하지 않고,\n조금씩 앞으로 나아가는 힘이 우리에겐 있으니까요.", source: "박찬호 야구 선수", category: "극복과 도전", type: "korean-author" },
  { text: "절대 포기하지 마세요.  \n어떠한 어려움이 찾아와도 마음을 굳게 먹고  \n한 걸음 한 걸음씩 앞으로 나아가는 것이 중요합니다.", source: "박찬호 야구 선수", category: "극복과 도전", type: "korean-author" },
  { text: "함께라면 어떤 어려움도 이겨낼 수 있어요.\n서로의 손을 꼭 잡고 나아갈 때, 세상 모든 일들이 가능해진답니다.  \n우리가 함께라면 불가능은 없어요.", source: "박찬호 야구 선수", category: "극복과 도전", type: "korean-author" },
  { text: "우리는 생각보다 훨씬 강한 존재예요.\n어려운 순간에도 마음속 깊은 곳에서 힘이 자라나니까요.\n서로를 믿고 나아가면 어떤 시련도 이겨낼 수 있어요.", source: "박찬호 야구 선수", category: "극복과 도전", type: "korean-author" },
  { text: "고통은 잠시 머물다 사라지는 손님과 같아요.\n지금 힘들어도 시간이 지나면 반드시 지나가고,\n그 자리에 더 단단한 나 자신이 남을 거예요.", source: "이순신 장군", category: "극복과 도전", type: "korean-author" },
  { text: "진실은 결국 우리 마음속 깊이 자리 잡아,\n어둠 속에서도 빛을 잃지 않아요. 시간이 지나도 변하지 않는 그 힘이\n마침내 모든 어려움을 이겨내게 해 줄 거예요.", source: "이순신 장군", category: "극복과 도전", type: "korean-author" },
  { text: "우리는 언제나 올바른 길을 선택해야 해요.\n비록 그 길이 쉽지 않을지라도,\n마음의 평화를 위해서라도 바른 길을 걷는 것이 중요하답니다.", source: "이순신 장군", category: "극복과 도전", type: "korean-author" },
  { text: "용기를 내어 한 걸음 내딛어 보세요.\n비록 두렵고 불확실해도,\n그 한 걸음이 당신의 세상을 바꿀 수 있으니까요.", source: "이순신 장군", category: "극복과 도전", type: "korean-author" },
  { text: "너는 이미 마음속 깊이 용기를 품고 있어요.\n때로는 두려움이 찾아와도,\n그 속에서도 충분히 앞으로 나아갈 힘이 있다는 걸 잊지 마세요.", source: "이순신 장군", category: "극복과 도전", type: "korean-author" },
  { text: "위기는 우리에게 찾아오는 뜻밖의 순간이에요.\n비록 두렵고 어려울지라도,\n그 안에는 새로운 시작과 성장의 기회가 숨어 있답니다.", source: "안철수 정치인", category: "극복과 도전", type: "korean-author" },
  { text: "절대 포기하지 말아라.  \n힘들고 지칠 때도 있겠지만,  \n그 순간이 지나면 더 강해진 자신을 만날 수 있을 거야.", source: "안철수 정치인", category: "극복과 도전", type: "korean-author" },
  { text: "우리는 마음을 모으면 무엇이든 해낼 수 있어요.\n작은 가능성을 믿는 순간, 그 힘은 점점 커져서 결국 우리를 이끌어 줄 거예요.", source: "안철수 정치인", category: "극복과 도전", type: "korean-author" },
  { text: "함께라면 우리는 더 큰 힘을 낼 수 있어요.\n서로의 손을 잡고 어려움을 이겨낼 때,\n그 어떤 시련도 두렵지 않답니다.", source: "안철수 정치인", category: "극복과 도전", type: "korean-author" },
  { text: "너는 이미 많은 어려움을 견뎌냈고,\n그 모든 순간들이 너를 더욱 단단하게 만들었어.  \n지금 이 순간에도 너는 충분히 강하고,\n앞으로 마주할 어떤 도전도 이겨낼 수 있을 거야.", source: "안철수 정치인", category: "극복과 도전", type: "korean-author" },
  { text: "고통이라는 시련의 순간들이야말로\n우리 안에 숨겨진 진정한 강함을 깨우는 시간입니다.\n힘들고 아플 때마다 조금씩 더 단단해지는 자신을 느껴보세요.", source: "김난도 교수", category: "극복과 도전", type: "korean-author" },
  { text: "성공은 결코 한순간에 이루어지지 않아요.\n작은 걸음 하나하나를 멈추지 않고 계속 나아갈 때,\n비로소 그 길 위에서 진정한 성취를 만날 수 있답니다.", source: "김난도 교수", category: "극복과 도전", type: "korean-author" },
  { text: "절대 포기하지 말아요.\n힘든 순간이 찾아와도,\n그 끝에는 반드시 새로운 희망이 기다리고 있으니까요.", source: "김난도 교수", category: "극복과 도전", type: "korean-author" },
  { text: "너는 이미 충분히 잘하고 있어요.\n때로는 스스로를 믿는 것이 가장 큰 힘이 되니까요.\n조금씩 나아가는 당신의 모습이 참 아름답답니다.", source: "김난도 교수", category: "극복과 도전", type: "korean-author" },
  { text: "최선을 다하는 것만으로도 충분해요.  \n결과에 연연하지 말고, 그 과정 속에서 스스로를 믿으며  \n한 걸음 한 걸음 정성을 다해 나아가면 됩니다.", source: "김난도 교수", category: "극복과 도전", type: "korean-author" },
  
  // 꿈과 목표
  { text: "꿈을 꾸는 것은 우리 마음속에 피어나는 작은 희망의 씨앗과 같아요.\n그 씨앗이 자라날 수 있도록 용기 있게 행동하며 한 걸음씩 나아갈 때,\n비로소 꿈은 현실이 되어 우리 곁에 찾아온답니다.", source: "박영선 국회의원", category: "꿈과 목표", type: "korean-author" },
  { text: "너의 꿈은 단순한 바람이 아니에요.\n그 꿈이 바로 너라는 사람을 만들어가고,\n세상에 너를 소개하는 가장 진실한 모습이랍니다.", source: "박영선 국회의원", category: "꿈과 목표", type: "korean-author" },
  { text: "목표를 향해 꾸준히 한 걸음씩 내딛는 것이 중요해요.\n비록 길이 멀고 험난해 보여도,\n포기하지 않고 나아가는 그 순간이 당신을 성장하게 할 거예요.", source: "박영선 국회의원", category: "꿈과 목표", type: "korean-author" },
  { text: "너의 꿈은 너만의 소중한 빛이 되어 줄 거예요.\n어떤 어려움이 와도 그 빛을 잃지 말고,\n끝까지 포기하지 않길 진심으로 응원할게요.", source: "박영선 국회의원", category: "꿈과 목표", type: "korean-author" },
  { text: "꿈은 단순한 생각에 머무르지 않고,\n꾸준한 노력과 믿음 속에서 조금씩 현실로 다가올 수 있어요.\n포기하지 않는 마음이야말로 꿈을 이루는 가장 큰 힘이랍니다.", source: "박영선 국회의원", category: "꿈과 목표", type: "korean-author" },
  { text: "목표는 언제나 분명해야 해요.\n그래야만 흔들리는 마음 속에서도 길을 잃지 않고,\n조금씩 나아갈 수 있으니까요.", source: "이순신 장군", category: "꿈과 목표", type: "korean-author" },
  { text: "목표를 향해 한 걸음씩 천천히 나아가세요.\n비록 길이 멀고 험해도,\n그 과정 속에서 당신만의 빛나는 이야기가 만들어질 거예요.", source: "이순신 장군", category: "꿈과 목표", type: "korean-author" },
  { text: "너의 마음속에 그려진 비전을 꼭 붙잡아 보세요.\n작은 꿈이라도 꾸준히 키워간다면,\n언젠가 그것이 눈앞의 현실이 되어 있을 거예요.", source: "이순신 장군", category: "꿈과 목표", type: "korean-author" },
  { text: "꿈을 이루는 길은 결코 쉽지 않아요.\n수많은 어려움과 고비가 있지만,\n그럼에도 불구하고 꿈은 언제나 가능하답니다.", source: "이순신 장군", category: "꿈과 목표", type: "korean-author" },
  { text: "목표가 없으면 우리는 어디로 가야 할지 몰라\n길을 잃은 채 헤매기 쉽습니다.  \n그러니 작은 꿈이라도 마음에 품고\n그 방향을 향해 한 걸음씩 나아가 보세요.", source: "이순신 장군", category: "꿈과 목표", type: "korean-author" },
  { text: "꿈을 이루기 위해서는 때로 소중한 것들을 내려놓아야 해요.\n희생이란 결국 자신을 더 단단하게 만들고,\n꿈에 한 걸음 더 가까워지게 하는 아름다운 과정이니까요.", source: "박경철 의사", category: "꿈과 목표", type: "korean-author" },
  { text: "목표를 향한 집중력은 우리 삶의 방향을 밝혀주는 등불과 같아요.\n그 빛을 따라 한 걸음씩 꾸준히 나아갈 때, 비로소 진정한 성공이라는 열매를 맺을 수 있답니다.", source: "박경철 의사", category: "꿈과 목표", type: "korean-author" },
  { text: "꿈은 크면 클수록 더 빛나고 아름다워져요.\n마음속에 큰 꿈을 품을수록,\n그 꿈을 향한 여정도 더욱 의미 있어집니다.", source: "박경철 의사", category: "꿈과 목표", type: "korean-author" },
  { text: "너의 꿈이 항상 너의 마음 깊은 곳에서 빛나며\n어둠 속에서도 길을 잃지 않게 이끌어 주어야 해요.\n그 꿈이 바로 너의 삶을 움직이는 힘이 되어 줄 거예요.", source: "박경철 의사", category: "꿈과 목표", type: "korean-author" },
  { text: "목표를 향해 한 걸음씩 천천히 나아가세요.  \n작은 발걸음 하나하나가 모여 결국 당신의 꿈을 이루는 길이 될 테니까요.  \n조급해하지 말고, 오늘의 걸음을 소중히 여기며 꾸준히 걸어가길 바랍니다.", source: "박경철 의사", category: "꿈과 목표", type: "korean-author" },
  { text: "꿈을 꾸는 것은 우리의 마음에 희망의 씨앗을 심는 일과 같아요.\n그 씨앗이 자라도록 행동으로 물을 주어야만,\n비로소 우리의 소망이 현실이 될 수 있답니다.", source: "유시민 작가", category: "꿈과 목표", type: "korean-author" },
  { text: "목표가 없으면 성공도 없다는 말이 있어요.  \n우리가 가고자 하는 방향이 분명할 때에만  \n비로소 그 길 위에서 작은 성취들을 쌓아갈 수 있답니다.", source: "유시민 작가", category: "꿈과 목표", type: "korean-author" },
  { text: "너의 마음속에 담긴 목표를 분명하게 그려봐요.\n그렇게 하면 흔들리는 순간에도 길을 잃지 않고,\n한 걸음씩 자신 있게 나아갈 수 있을 거예요.", source: "유시민 작가", category: "꿈과 목표", type: "korean-author" },
  { text: "목표를 향해 한 걸음 한 걸음 꾸준히 나아가세요.\n비록 길이 멀고 어려워 보여도,\n그 여정 속에서 당신만의 빛나는 이야기가 만들어질 거예요.", source: "유시민 작가", category: "꿈과 목표", type: "korean-author" },
  { text: "꿈은 단순한 희망이 아니라,\n조금씩 현실로 다가올 수 있는 소중한 씨앗이에요.\n조심스레 가꾸면 어느새 눈앞에 펼쳐진답니다.", source: "유시민 작가", category: "꿈과 목표", type: "korean-author" },
  
  // 자신감과 용기
  { text: "너는 있는 그대로의 모습으로도 충분히 아름답고 소중해요.\n다른 누구와도 비교할 필요 없이,\n그 자체로 완전한 존재임을 기억해 주세요.", source: "이효리 가수", category: "자신감과 용기", type: "korean-author" },
  { text: "자신을 믿는 마음이야말로 가장 큰 힘이 되어줍니다.\n어떤 어려움이 와도 흔들리지 말고,\n한 걸음씩 용기 있게 앞으로 나아가세요.", source: "이효리 가수", category: "자신감과 용기", type: "korean-author" },
  { text: "너 자신이 얼마나 소중한 존재인지 꼭 기억해 줘요.\n다른 누구도 아닌 바로 너만이 가진 특별한 빛이 있으니까요.\n그 가치를 잊지 않고 스스로를 사랑하는 마음을 지켜 나가길 바랍니다.", source: "이효리 가수", category: "자신감과 용기", type: "korean-author" },
  { text: "두려움은 결코 약함이 아니에요.\n오히려 마음이 여리고 섬세하다는 증거일 뿐이죠.\n그 두려움을 마주하는 용기야말로 진정한 강함입니다.", source: "이효리 가수", category: "자신감과 용기", type: "korean-author" },
  { text: "너는 이미 이 세상에 하나뿐인 소중한 존재예요.\n때로는 자신을 의심할 때도 있겠지만,\n결코 잊지 마세요, 너는 충분히 훌륭하다는 것을.", source: "이효리 가수", category: "자신감과 용기", type: "korean-author" },
  { text: "용기란 두려움이 마음속을 가득 채울 때에도\n한 걸음 앞으로 나아가는 힘이에요.  \n두려움을 피하지 않고 마주할 때,  \n비로소 진정한 용기가 우리 안에 자라납니다.", source: "강남 래퍼", category: "자신감과 용기", type: "korean-author" },
  { text: "네가 진심으로 믿는 그 신념을 언제나 지켜나가야 해요.\n세상의 바람이 거세도 흔들리지 않고,\n그 마음이 너를 더욱 빛나게 할 거예요.", source: "강남 래퍼", category: "자신감과 용기", type: "korean-author" },
  { text: "영웅이란 두려움이 없는 사람이 아니라,\n그 두려움을 마주하며 용기 있게 이겨내는 사람입니다.\n진정한 용기는 마음속 깊은 두려움을 넘어설 때 피어나는 법이니까요.", source: "강남 래퍼", category: "자신감과 용기", type: "korean-author" },
  { text: "너는 언제나 너 자신의 가장 큰 영웅이에요.\n어떤 어려움 앞에서도 스스로를 믿고 일어서는 그 마음이야말로 진정한 용기랍니다.\n그러니 가끔은 스스로를 칭찬하고, 네 안에 숨겨진 힘을 기억해 주세요.", source: "강남 래퍼", category: "자신감과 용기", type: "korean-author" },
  { text: "자신감은 우리 마음속에 숨겨진 소중한 열쇠와 같아요.\n그 열쇠를 잡는 순간, 우리는 성공이라는 문을 두드릴 수 있게 되지요.\n그러니 스스로를 믿고 한 걸음 내딛는 용기를 잃지 마세요.", source: "강남 래퍼", category: "자신감과 용기", type: "korean-author" },
  { text: "너는 이미 그 힘을 품고 있어요.\n어떤 어려움이 와도,\n스스로를 믿으면 반드시 해낼 수 있답니다.", source: "박찬호 야구 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "너는 이미 많은 어려움을 견뎌냈고,\n그 과정에서 스스로 얼마나 강한지 알게 되었을 거야.\n때로 지치고 힘들어도, 너는 충분히 이겨낼 힘을 가지고 있어.", source: "박찬호 야구 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "약점은 누구나 가지고 있는 소중한 부분이에요.\n그것을 두려워하지 말고,\n오히려 강점으로 바꾸어 나가는 용기를 가지세요.", source: "박찬호 야구 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "너의 마음 깊은 곳에서 우러나오는 목소리를 두려워하지 말고 내어 보세요.\n그 소리는 세상에 꼭 필요한 빛이 되어,\n누군가의 마음에도 따스한 울림을 전할 거예요.", source: "박찬호 야구 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "두려움을 마주하고 용기 내어 한 걸음 나아갈 때,\n그 자리에 조금씩 자신감이 쌓여갑니다.\n두려움을 이겨낸 경험이 당신을 더 강하고 빛나게 만들어 줄 거예요.", source: "박찬호 야구 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "너는 이미 그 자체로 충분히 소중하고 귀한 존재예요.\n어떤 순간에도 스스로의 가치를 잊지 말고,\n당당하게 빛나길 바랍니다.", source: "김연아 피겨 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "너의 마음 깊은 곳에 숨겨진 가능성을 믿어보세요.\n아직 발견되지 않은 힘들이 당신 안에 살아 숨 쉬고 있으니까요.\n그 믿음이 당신을 더 멀리, 더 높이 이끌어 줄 거예요.", source: "김연아 피겨 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "과거는 이미 지나간 시간일 뿐이에요.\n그 안에 머무르기보다, 지금 이 순간을 살아가며\n새로운 내일을 향해 한 걸음씩 나아가는 것이 중요해요.", source: "김연아 피겨 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "미래는 이미 정해진 것이 아니에요.\n그것은 바로 당신의 손끝에서 만들어져 가는 이야기랍니다.\n당신이 어떤 선택을 하느냐에 따라 달라질 수 있으니,\n용기 내어 한 걸음씩 나아가 보세요.", source: "김연아 피겨 선수", category: "자신감과 용기", type: "korean-author" },
  { text: "너 자신을 사랑하는 일은 가장 소중한 시작입니다.\n내 안의 빛과 그림자까지 따뜻하게 안아줄 때,\n진정한 행복이 찾아올 거예요.", source: "김연아 피겨 선수", category: "자신감과 용기", type: "korean-author" },
  
  // 우정과 응원
  { text: "친구는 우리 삶의 소중한 가족과 같아요.\n서로의 마음을 이해하고 지켜주며,\n함께할 때 진정한 따뜻함을 느낄 수 있답니다.", source: "박경철 의사", category: "우정과 응원", type: "korean-author" },
  { text: "함께라면 어떤 어려움도 이겨낼 수 있어요.\n서로의 손을 잡고 나아가면, 불가능해 보였던 일들도\n조금씩 현실이 되어가는 마법 같은 순간을 경험하게 될 거예요.", source: "박경철 의사", category: "우정과 응원", type: "korean-author" },
  { text: "너를 진심으로 믿어주는 친구 한 사람이 있다는 것만으로도\n세상 어떤 어려움도 이겨낼 힘이 생겨나지요.\n그 믿음이 당신의 가장 큰 버팀목이 되어 줄 거예요.", source: "박경철 의사", category: "우정과 응원", type: "korean-author" },
  { text: "친구와 함께 나눈 소중한 추억들은 시간이 흘러도 변치 않는 마음의 보물이에요.\n그 기억들이 우리를 따뜻하게 감싸주며,\n삶의 힘이 되어 준답니다.", source: "박경철 의사", category: "우정과 응원", type: "korean-author" },
  { text: "친구는 우리 삶에 큰 변화를 가져다줍니다.\n어려울 때 곁에 있어 주고, 웃음과 위로를 나누며\n당신의 인생을 더욱 아름답고 특별하게 만들어 줍니다.", source: "박경철 의사", category: "우정과 응원", type: "korean-author" },
  { text: "함께 웃을 때는 그 기쁨이 두 배가 되고,\n함께 울 때는 그 슬픔이 절반으로 줄어듭니다.\n서로의 마음을 나누며 살아가는 것이 진정한 행복이니까요.", source: "유시민 작가", category: "우정과 응원", type: "korean-author" },
  { text: "사랑하는 사람들과 함께하는 시간은\n우리 마음에 가장 따뜻한 빛을 선물해 줍니다.\n그들과 함께 있을 때 비로소 삶이 더 깊고 풍성해지지요.", source: "유시민 작가", category: "우정과 응원", type: "korean-author" },
  { text: "가장 소중한 것은 바로 곁에 있는 사람들입니다.\n가족과 친구는 세상 그 무엇과도 바꿀 수 없는\n진정한 보물이라는 것을 잊지 마세요.", source: "유시민 작가", category: "우정과 응원", type: "korean-author" },
  { text: "함께하는 시간은 무엇과도 바꿀 수 없는 소중한 순간이에요.\n서로의 온기를 나누며 마음이 한층 더 가까워질 때,\n그 시간이 가장 아름답게 빛나지요.", source: "유시민 작가", category: "우정과 응원", type: "korean-author" },
  { text: "너의 곁에는 언제나 너를 응원하는 사람이 있어요.\n때로는 힘들고 지칠 때도 있겠지만,\n그 사람이 있기에 혼자가 아님을 느낄 수 있을 거예요.", source: "유시민 작가", category: "우정과 응원", type: "korean-author" },
  { text: "친구의 따뜻한 응원은 마음 깊은 곳에서부터 큰 힘이 되어줍니다.\n힘들고 지칠 때마다 그 응원이 나를 일으켜 세우고,\n다시 앞으로 나아갈 용기를 주지요.", source: "이어령 교수", category: "우정과 응원", type: "korean-author" },
  { text: "언제나 혼자가 아니라는 사실을 마음 깊이 새기세요.\n어두운 순간에도 누군가는 당신의 곁에 있고,\n그 따뜻한 존재가 당신을 지켜주고 있다는 걸 잊지 마세요.", source: "이어령 교수", category: "우정과 응원", type: "korean-author" },
  { text: "진정한 친구는 세상에서 가장 소중한 보물과 같아요.\n어려울 때나 기쁠 때나 항상 곁에 있어 주는 그들이야말로\n우리 인생의 가장 큰 자산임을 잊지 마세요.", source: "이어령 교수", category: "우정과 응원", type: "korean-author" },
  { text: "함께할 때 우리는 더 큰 힘을 낼 수 있어요.\n서로의 마음과 손을 맞잡고 나아가면,\n어떤 어려움도 이겨낼 수 있답니다.", source: "이어령 교수", category: "우정과 응원", type: "korean-author" },
  { text: "친구가 나를 믿어줄 때, 그 믿음은 내 안에 큰 힘이 되어줘요.\n혼자라고 느껴질 때도, 그 믿음이 나를 지탱하며 더 강해지게 만들죠.  \n그래서 우리는 서로의 믿음 속에서 함께 성장할 수 있어요.", source: "이어령 교수", category: "우정과 응원", type: "korean-author" },
  { text: "너를 항상 응원해 주는 사람들이 곁에 있어요.\n때로는 힘들고 외로워도, 그들이 있기에\n당신은 혼자가 아니란 걸 잊지 말아요.", source: "조용필 가수", category: "우정과 응원", type: "korean-author" },
  { text: "함께라면 어떤 어려움도 이겨낼 수 있어요.\n서로의 손을 잡고 걸어가면 두려움은 자연스레 사라지고,\n마음 속 깊은 곳에 따뜻한 용기가 피어납니다.", source: "조용필 가수", category: "우정과 응원", type: "korean-author" },
  { text: "친구는 언제나 네 곁에서\n가장 큰 힘이 되어주는 존재예요.\n서로의 마음을 따뜻하게 감싸 안으며,\n함께라서 더 강해질 수 있답니다.", source: "조용필 가수", category: "우정과 응원", type: "korean-author" },
  { text: "함께 나누는 기쁨은 그 무엇과도 바꿀 수 없는 소중한 순간이에요.\n서로의 마음을 나누며 더 깊어지는 행복이야말로 진정한 기쁨이죠.  \n우리가 함께할 때, 그 기쁨은 배가되어 오래도록 기억에 남는답니다.", source: "조용필 가수", category: "우정과 응원", type: "korean-author" },
  { text: "친구의 응원이 없이는 진정한 성공을 이루기 어렵습니다.\n서로가 서로의 힘이 되어줄 때, 비로소 우리는 꿈을 향해 한 걸음 더 나아갈 수 있지요.\n함께하는 마음이 있기에 성공은 더욱 값지고 빛나는 법입니다.", source: "조용필 가수", category: "우정과 응원", type: "korean-author" },
];
